	CONSTRAINT "telegram_identity_mappings_pk" PRIMARY KEY("organization_id","id"),
	CONSTRAINT "telegram_identity_org_user_chat_unique" UNIQUE("organization_id","telegram_user_id","telegram_chat_id")
);

CREATE TABLE "users" (
