DROP FUNCTION IF EXISTS indicate_private.fail_invalidation(p_organization_id uuid, p_task_id uuid, p_claim_token uuid, p_failure jsonb, p_next_attempt_at timestamptz, p_terminal boolean, p_now timestamptz);
