-- ----------------------------------------------------------------------
-- 20260925160000_upt_city_affiliations_all_domains
-- ----------------------------------------------------------------------
-- Extend the UPT city affiliations to every Domain.
--
-- Migration v181 recorded the documented 59 institutional claims on the ten
-- domains that run the prisoner-affiliation network. Every Domain now carries
-- the same 31-city Jawa Tengah roster, so the same verified institutional
-- relationship applies to each of them: 59 x 104 = 6136 rows, of which 590 are
-- already present. The claim shape is unchanged (`claim_scopes=['site_name']`,
-- `evidence_reference='direktori-resmi'`, active and verified), the institution
-- name always comes from the publisher record rather than the request, and the
-- guard block still refuses to write unless all 59 pairs resolve to exactly one
-- publisher and one city geography and the total reaches 59 per Domain.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
WITH source(city_slug, publisher_name) AS (
  VALUES
    ('cilacap', 'LAPAS KELAS I BATU NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS KELAS II A BESI NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS KHUSUS KELAS II A KARANGANYAR NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS KELAS II A KEMBANG KUNING NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS KELAS II A GLADAKAN NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS KELAS II A KUMBANG NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS KELAS II A NGASEMAN NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS NARKOTIKA KELAS II A NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS KELAS II A PASIR PUTIH NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS KELAS II A PERMISAN NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS KELAS II B NIRBAYA NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS TERBUKA KELAS II B NUSAKAMBANGAN'),
    ('cilacap', 'LAPAS KELAS II B CILACAP'),
    ('cilacap', 'BAPAS KELAS II NUSAKAMBANGAN'),
    ('semarang', 'LAPAS KELAS I SEMARANG'),
    ('semarang', 'LAPAS PEREMPUAN KELAS II A SEMARANG'),
    ('semarang', 'RUTAN KELAS I SEMARANG'),
    ('semarang', 'BAPAS KELAS I SEMARANG'),
    ('semarang', 'LAPAS KELAS II A AMBARAWA'),
    ('banyumas', 'LAPAS KELAS II A PURWOKERTO'),
    ('banyumas', 'LAPAS NARKOTIKA KELAS II B PURWOKERTO'),
    ('banyumas', 'RUTAN KELAS II B BANYUMAS'),
    ('banyumas', 'BAPAS KELAS II PURWOKERTO'),
    ('kendal', 'LAPAS KELAS II A KENDAL'),
    ('kendal', 'LAPAS TERBUKA KELAS II B KENDAL'),
    ('kendal', 'LAPAS PEMUDA KELAS II B PLANTUNGAN'),
    ('pekalongan', 'LAPAS KELAS II A PEKALONGAN'),
    ('pekalongan', 'RUTAN KELAS II A PEKALONGAN'),
    ('pekalongan', 'BAPAS KELAS II PEKALONGAN'),
    ('magelang', 'LAPAS KELAS II A MAGELANG'),
    ('magelang', 'BAPAS KELAS II MAGELANG'),
    ('tegal', 'LAPAS KELAS II B TEGAL'),
    ('tegal', 'LAPAS KELAS II B SLAWI'),
    ('klaten', 'LAPAS KELAS II B KLATEN'),
    ('klaten', 'BAPAS KELAS II KLATEN'),
    ('pati', 'LAPAS KELAS II B PATI'),
    ('pati', 'BAPAS KELAS II PATI'),
    ('purworejo', 'LPKA KELAS I KUTOARJO'),
    ('purworejo', 'RUTAN KELAS II B PURWOREJO'),
    ('surakarta', 'RUTAN KELAS I SURAKARTA'),
    ('surakarta', 'BAPAS KELAS I SURAKARTA'),
    ('banjarnegara', 'RUTAN KELAS II B BANJARNEGARA'),
    ('batang', 'LAPAS KELAS II B BATANG'),
    ('blora', 'RUTAN KELAS II B BLORA'),
    ('boyolali', 'RUTAN KELAS II B BOYOLALI'),
    ('brebes', 'LAPAS KELAS II B BREBES'),
    ('demak', 'RUTAN KELAS II B DEMAK'),
    ('grobogan', 'LAPAS KELAS II B PURWODADI'),
    ('jepara', 'RUTAN KELAS II B JEPARA'),
    ('kebumen', 'RUTAN KELAS II B KEBUMEN'),
    ('kudus', 'RUTAN KELAS II B KUDUS'),
    ('pemalang', 'RUTAN KELAS II B PEMALANG'),
    ('purbalingga', 'RUTAN KELAS II B PURBALINGGA'),
    ('rembang', 'RUTAN KELAS II B REMBANG'),
    ('salatiga', 'RUTAN KELAS II B SALATIGA'),
    ('sragen', 'LAPAS KELAS II A SRAGEN'),
    ('temanggung', 'RUTAN KELAS II B TEMANGGUNG'),
    ('wonogiri', 'LAPAS KELAS II B WONOGIRI'),
    ('wonosobo', 'RUTAN KELAS II B WONOSOBO')
), resolved AS (
  SELECT geography.organization_id,
         network.id AS domain_id,
         source.publisher_name,
         publisher.id AS publisher_id,
         city_portal.id AS site_id
    FROM source
    JOIN public.regions AS geography
      ON geography.kind = 'city' AND geography.slug = source.city_slug
    JOIN public.publishers AS publisher
      ON publisher.organization_id = geography.organization_id AND publisher.name = source.publisher_name
    JOIN public.sites AS city_portal
      ON city_portal.organization_id = geography.organization_id
     AND city_portal.region_id = geography.id
     AND city_portal.site_level = 'city'
    JOIN public.domains AS network
      ON network.organization_id = geography.organization_id
     AND network.id = city_portal.domain_id
), inserted AS (
  INSERT INTO public.official_affiliations (
    organization_id, id, publisher_id, site_id, institution_name, claim_scopes,
    evidence_reference, active, verified_at, version, created_at, updated_at
  )
  SELECT resolved.organization_id,
         gen_random_uuid(),
         resolved.publisher_id,
         resolved.site_id,
         resolved.publisher_name,
         ARRAY['site_name']::text[],
         'direktori-resmi',
         true,
         now(),
         1,
         now(),
         now()
    FROM resolved
   WHERE NOT EXISTS (
     SELECT 1 FROM public.official_affiliations AS existing
      WHERE existing.organization_id = resolved.organization_id
        AND existing.publisher_id = resolved.publisher_id
        AND existing.site_id = resolved.site_id
   )
  RETURNING organization_id, site_id
)
INSERT INTO public.audit_logs (
  organization_id, id, actor_type, actor_id, entry_point, action, target_type, target_id,
  outcome, changed_fields, after, request_id
)
SELECT DISTINCT organization_id,
       gen_random_uuid(),
       'system'::public.audit_actor_type,
       'migration:upt_city_affiliations_all_domains',
       'worker'::public.audit_entry_point,
       'affiliation.verify',
       'official_affiliation',
       site_id::text,
       'succeeded'::public.audit_outcome,
       ARRAY['publisherId', 'siteId', 'claimScopes', 'evidenceReference'],
       jsonb_build_object('claimScopes', ARRAY['site_name'], 'evidenceReference', 'direktori-resmi'),
       'migration:184'
  FROM inserted
 LIMIT ALL;
DO $$
DECLARE
  domains_total integer;
  per_domain integer;
  minimum_per_domain integer;
  maximum_per_domain integer;
  on_non_city integer;
BEGIN
  SELECT count(*) INTO domains_total FROM public.domains;

  SELECT min(claims), max(claims) INTO minimum_per_domain, maximum_per_domain
    FROM (
      SELECT site.domain_id, count(a.id) AS claims
        FROM public.sites AS site
        JOIN public.official_affiliations AS a ON a.site_id = site.id
       WHERE site.site_level = 'city'
       GROUP BY site.domain_id
    ) AS per_domain_rows;

  SELECT count(*) INTO per_domain
    FROM public.official_affiliations
   WHERE evidence_reference = 'direktori-resmi';

  SELECT count(*) INTO on_non_city
    FROM public.official_affiliations AS a
    JOIN public.sites AS s ON s.id = a.site_id
   WHERE s.site_level <> 'city';

  IF minimum_per_domain IS NULL OR minimum_per_domain <> 59 OR maximum_per_domain <> 59 THEN
    RAISE EXCEPTION 'upt_affiliation_incomplete: per-domain claims range %, expected 59', minimum_per_domain;
  END IF;
  IF per_domain <> 59 * domains_total THEN
    RAISE EXCEPTION 'upt_affiliation_incomplete: % claims for 59 institutions across % domains', per_domain, domains_total;
  END IF;
  IF on_non_city > 0 THEN
    RAISE EXCEPTION 'upt_affiliation_incomplete: % claims landed on a non-city portal', on_non_city;
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (184, 'upt_city_affiliations_all_domains', 'sha256:ac56dfee648bf3b7205de8498021a03241de401216e0d1b1788d6cad913d4cd4');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('77f9fcd4933248ade39486dd40757f370dcf527dd3b6269e04fdcdc228da08d7', 1790390400000);

-- ----------------------------------------------------------------------
-- 20260925170000_region_scope_session_independence
-- ----------------------------------------------------------------------
-- Make region_scope_covers independent of the request session.
--
-- The helper filtered its subtree lookup on
-- `indicate_private.current_organization_id()`, which made the predicate
-- unusable outside a request context (a direct call returned false for a child
-- city) and coupled a pure geography question to session state. The filter was
-- also redundant: `regions_parent_fk` is a composite foreign key on
-- `(organization_id, parent_region_id)`, so a city and its parent province are
-- always in the same organization. A match on `parent_region_id` is therefore
-- already same-organization, and every policy keeps its own
-- `organization_id = current_organization_id()` conjunct next to the helper.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
CREATE OR REPLACE FUNCTION indicate_private.region_scope_covers(p_scope uuid, p_candidate uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = pg_catalog, public, indicate_private
AS $$
  SELECT p_scope IS NULL
      OR p_candidate IS NULL
      OR p_candidate = p_scope
      OR EXISTS (
        SELECT 1
          FROM public.regions AS region
         WHERE region.id = p_candidate
           AND region.parent_region_id = p_scope
      );
$$;
DO $$
DECLARE
  province uuid;
  city uuid;
  sibling_city uuid;
BEGIN
  SELECT id INTO province FROM public.regions WHERE slug = 'jawa-tengah' AND kind = 'region';
  SELECT id INTO city FROM public.regions WHERE slug = 'wonosobo' AND kind = 'city';
  SELECT id INTO sibling_city FROM public.regions WHERE slug = 'semarang' AND kind = 'city';

  IF NOT indicate_private.region_scope_covers(NULL, city) THEN
    RAISE EXCEPTION 'region_scope_regression: an unrestricted scope must cover any geography';
  END IF;
  IF NOT indicate_private.region_scope_covers(province, NULL) THEN
    RAISE EXCEPTION 'region_scope_regression: an apex portal must stay visible to a scoped actor';
  END IF;
  IF NOT indicate_private.region_scope_covers(province, province) THEN
    RAISE EXCEPTION 'region_scope_regression: a scope must cover itself';
  END IF;
  IF NOT indicate_private.region_scope_covers(province, city) OR NOT indicate_private.region_scope_covers(province, sibling_city) THEN
    RAISE EXCEPTION 'region_scope_regression: every city under the scope must be covered';
  END IF;
  IF indicate_private.region_scope_covers(city, sibling_city) THEN
    RAISE EXCEPTION 'region_scope_regression: a city scope must not reach a sibling city';
  END IF;
  IF indicate_private.region_scope_covers(city, province) THEN
    RAISE EXCEPTION 'region_scope_regression: a city scope must not reach its parent province';
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (185, 'region_scope_session_independence', 'sha256:81675ec391c43324fc3880a3f6753c3175db9548a4c502c1989f5bc8eafc8f9b');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('31550afde5fe330a94c668e1afb7015ded712df6002f2d788a6a583313451caa', 1790394000000);

-- ----------------------------------------------------------------------
-- 20260925180000_media_shared_brand_guard
-- ----------------------------------------------------------------------
-- Protect a media asset that many portals display.
--
-- One apex brand image is the single source for the whole network: the apex, its
-- province portal, and its 31 city portals all point at the same `media` row
-- (3328 sites, 114 distinct default images). That sharing is deliberate and
-- public delivery already authorizes it, but it also meant a single archive
-- could quietly strip the image from 32 live portals, and a delete surfaced a
-- bare foreign-key error. The database now refuses both with an actionable
-- message naming how many portals depend on the asset.
--
-- The supported order is therefore: repoint the brand first, then archive the
-- old asset. `saveSiteSettings` repoints every derived portal in the same
-- transaction when an apex default changes, so that order is a single action in
-- the dashboard.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
CREATE OR REPLACE FUNCTION indicate_private.guard_shared_media()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, public, indicate_private
AS $$
DECLARE
  dependent_sites integer;
  action constant text := CASE WHEN TG_OP = 'DELETE' THEN 'deleted' ELSE 'archived' END;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.state = 'active' THEN
    RETURN NEW;
  END IF;

  SELECT count(*) INTO dependent_sites
    FROM public.site_settings
   WHERE organization_id = OLD.organization_id
     AND (default_media_id = OLD.id OR logo_media_id = OLD.id OR favicon_media_id = OLD.id);

  IF dependent_sites > 0 THEN
    RAISE EXCEPTION
      'media is still displayed by % portal(s); repoint the brand media first, then archive it',
      dependent_sites
      USING ERRCODE = '23503';
  END IF;

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;
DROP TRIGGER IF EXISTS media_shared_guard ON public.media;
CREATE TRIGGER media_shared_guard
  BEFORE DELETE OR UPDATE OF state ON public.media
  FOR EACH ROW EXECUTE FUNCTION indicate_private.guard_shared_media();
DO $$
DECLARE
  shared_assets integer;
  protected_rows integer;
BEGIN
  SELECT count(*) INTO shared_assets
    FROM (
      SELECT media.id
        FROM public.media
        JOIN public.site_settings
          ON site_settings.organization_id = media.organization_id
         AND media.id IN (site_settings.default_media_id, site_settings.logo_media_id, site_settings.favicon_media_id)
       GROUP BY media.id
      HAVING count(*) > 1
    ) AS shared;
  IF shared_assets = 0 THEN
    RAISE EXCEPTION 'media_shared_guard_degenerate: no shared brand asset found to protect';
  END IF;

  SELECT count(*) INTO protected_rows
    FROM public.media
   WHERE id IN (
     SELECT unnest(ARRAY[default_media_id, logo_media_id, favicon_media_id]) FROM public.site_settings
      WHERE default_media_id IS NOT NULL OR logo_media_id IS NOT NULL OR favicon_media_id IS NOT NULL
   );
  IF protected_rows = 0 THEN
    RAISE EXCEPTION 'media_shared_guard_degenerate: no media row is referenced by portal settings';
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (186, 'media_shared_brand_guard', 'sha256:56076092edb09422f8198da0383f1fe5e5c780550f7faea9cc24d9fe4c9f267f');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('7e975918223878f9f726139e07de7de85ea2edaa9f61b2a7d52d68943277b1fe', 1790397600000);

-- ----------------------------------------------------------------------
-- 20260925210000_indonesia_province_roster
-- ----------------------------------------------------------------------
-- Seed the national province roster and give every geography a short public name.
--
-- The network carried a single province, Jawa Tengah, because that was the
-- pilot. Operators need the whole archipelago available before any of it is
-- published: a city roster can only attach to a province that exists, and
-- `regions` is the parent every city geography and every region portal hangs
-- from. This migration writes all 38 first-level provinces for every
-- organization that already carries geography. It is data only, so nothing
-- customer-visible changes: no portal, no site, no hostname, no cache entry.
--
-- Naming has three jobs and therefore three fields:
--   name       official name, shown to readers and used in SEO text
--   short_name familiar public label (Jateng, Jabar, DIY) for dense UI
--   slug       DNS label, formal kebab, matching the city slugs already live
--              (`banjarnegara`, `surakarta`) and the existing
--              `jawa-tengah.{apex}` region portals, so no live hostname moves
-- `external_key` stays the machine key and keeps following the slug, which is
-- what the dashboard region form has always written and what nothing else in
-- the schema references.
--
-- `short_name` is nullable on purpose: a geography without a well-known short
-- form should not invent one, and readers fall back to `name`.
--
-- This is version 188, not 187. Production already carries a ledger row 187
-- named `author_newsroom_profile`, applied outside this repository; it left no
-- schema object behind, so the sequence simply continues past it and the ledger
-- stays monotonic. The gap is recorded here so nobody renumbers into it.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
ALTER TABLE public.regions ADD COLUMN short_name text;
ALTER TABLE public.regions
  ADD CONSTRAINT regions_short_name_length_check
  CHECK (short_name IS NULL OR char_length(short_name) BETWEEN 1 AND 40);
INSERT INTO public.regions (
  organization_id, id, external_key, name, short_name, slug, status, kind, parent_region_id, version
)
SELECT tenant.organization_id,
       gen_random_uuid(),
       roster.slug,
       roster.name,
       roster.short_name,
       roster.slug,
       'active'::public.record_status,
       'region'::public.region_kind,
       NULL,
       1
  FROM (VALUES
    ('Aceh', 'Aceh', 'aceh'),
    ('Sumatera Utara', 'Sumut', 'sumatera-utara'),
    ('Sumatera Barat', 'Sumbar', 'sumatera-barat'),
    ('Riau', 'Riau', 'riau'),
    ('Jambi', 'Jambi', 'jambi'),
    ('Sumatera Selatan', 'Sumsel', 'sumatera-selatan'),
    ('Bengkulu', 'Bengkulu', 'bengkulu'),
    ('Lampung', 'Lampung', 'lampung'),
    ('Kepulauan Bangka Belitung', 'Babel', 'bangka-belitung'),
    ('Kepulauan Riau', 'Kepri', 'kepulauan-riau'),
    ('Daerah Khusus Jakarta', 'DKI', 'dki-jakarta'),
    ('Jawa Barat', 'Jabar', 'jawa-barat'),
    ('Daerah Istimewa Yogyakarta', 'DIY', 'di-yogyakarta'),
    ('Jawa Timur', 'Jatim', 'jawa-timur'),
    ('Banten', 'Banten', 'banten'),
    ('Bali', 'Bali', 'bali'),
    ('Nusa Tenggara Barat', 'NTB', 'nusa-tenggara-barat'),
    ('Nusa Tenggara Timur', 'NTT', 'nusa-tenggara-timur'),
    ('Kalimantan Barat', 'Kalbar', 'kalimantan-barat'),
    ('Kalimantan Tengah', 'Kalteng', 'kalimantan-tengah'),
    ('Kalimantan Selatan', 'Kalsel', 'kalimantan-selatan'),
    ('Kalimantan Timur', 'Kaltim', 'kalimantan-timur'),
    ('Kalimantan Utara', 'Kalut', 'kalimantan-utara'),
    ('Sulawesi Utara', 'Sulut', 'sulawesi-utara'),
    ('Sulawesi Tengah', 'Sulteng', 'sulawesi-tengah'),
    ('Sulawesi Selatan', 'Sulsel', 'sulawesi-selatan'),
    ('Sulawesi Tenggara', 'Sultra', 'sulawesi-tenggara'),
    ('Gorontalo', 'Gorontalo', 'gorontalo'),
    ('Sulawesi Barat', 'Sulbar', 'sulawesi-barat'),
    ('Maluku', 'Maluku', 'maluku'),
    ('Maluku Utara', 'Malut', 'maluku-utara'),
    ('Papua Barat', 'Papua Barat', 'papua-barat'),
    ('Papua Barat Daya', 'Papua Barat Daya', 'papua-barat-daya'),
    ('Papua', 'Papua', 'papua'),
    ('Papua Selatan', 'Papua Selatan', 'papua-selatan'),
    ('Papua Tengah', 'Papua Tengah', 'papua-tengah'),
    ('Papua Pegunungan', 'Papua Pegunungan', 'papua-pegunungan')
  ) AS roster(name, short_name, slug)
  CROSS JOIN (SELECT DISTINCT organization_id FROM public.regions) AS tenant
 WHERE NOT EXISTS (
         SELECT 1 FROM public.regions AS existing
          WHERE existing.organization_id = tenant.organization_id
            AND existing.slug = roster.slug
       );
UPDATE public.regions
   SET short_name = 'Jateng'
 WHERE slug = 'jawa-tengah' AND kind = 'region' AND short_name IS NULL;
DO $$
DECLARE
  tenants integer;
  provinces integer;
  cities integer;
  incomplete integer;
  collisions text;
  orphan_portals integer;
BEGIN
  SELECT count(DISTINCT organization_id) INTO tenants FROM public.regions;
  SELECT count(*) INTO provinces FROM public.regions WHERE kind = 'region';
  SELECT count(*) INTO cities FROM public.regions WHERE kind = 'city';
  IF provinces <> tenants * 38 THEN
    RAISE EXCEPTION 'province_roster_incomplete: % provinces for % tenant(s), expected %', provinces, tenants, tenants * 38;
  END IF;
  IF cities <> tenants * 31 THEN
    RAISE EXCEPTION 'province_roster_changed: % cities for % tenant(s), expected %', cities, tenants, tenants * 31;
  END IF;
  SELECT count(*) INTO incomplete
    FROM public.regions
   WHERE kind = 'region' AND (short_name IS NULL OR parent_region_id IS NOT NULL OR status <> 'active');
  IF incomplete > 0 THEN
    RAISE EXCEPTION 'province_roster_incomplete: % province row(s) without a short name, a parent, or active status', incomplete;
  END IF;
  SELECT string_agg(format('%s (city %s) = %s (province)', city.slug, city.name, province.name), ', ')
    INTO collisions
    FROM public.regions AS province
    JOIN public.regions AS city
      ON city.organization_id = province.organization_id
     AND city.kind = 'city'
     AND province.kind = 'region'
     AND city.slug = province.slug;
  IF collisions IS NOT NULL THEN
    RAISE EXCEPTION 'province_roster_incomplete: slug collision %', collisions;
  END IF;
  SELECT count(*) INTO orphan_portals
    FROM public.sites
   WHERE site_level <> 'apex'
     AND NOT EXISTS (
       SELECT 1 FROM public.regions AS geography
        WHERE geography.organization_id = sites.organization_id
          AND geography.id = sites.region_id
     );
  IF orphan_portals > 0 THEN
    RAISE EXCEPTION 'province_roster_incomplete: % derived portal(s) lost their geography', orphan_portals;
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (188, 'indonesia_province_roster', 'sha256:b1c106df4e7eda822f6595b102e1eff4b2b2ef4f0b58bdfc2b03ddd65167dc3d');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('024e9256e5c2a531d20f641f748fbb07ef546f74e91dc7f0653fbee801ecb743', 1790404800000);

-- ----------------------------------------------------------------------
-- 20260925220000_media_reservation_expiry
-- ----------------------------------------------------------------------
-- Let an expired media key reservation release its object key.
--
-- `media_key_reservations_object_key_unique` was a plain unique index on
-- `object_key`, and `reserveMediaKey` inserts with ON CONFLICT DO NOTHING on
-- that key, answering `occupied` whenever any row already claims it. Nothing
-- ever expired or deleted those rows: `retention_sweep` covers five
-- operational queues but not this one, and no code path writes the `expired`
-- status at all. One reservation is stuck in exactly that state today,
-- reserved on 2026-09-23, past its expiry, with no `media` row for the object
-- it claimed, so that key can never be reserved again and the failure is
-- silent.
--
-- The index becomes partial: an `expired` row keeps the audit trail but stops
-- blocking the key. Postgres has no partial unique *constraint*, only a partial
-- unique index, so the constraint is dropped and the guarantee is restated as
-- that index. `retention_sweep` gains a `media_key_reservations` category that
-- expires reservations past their deadline which never produced media, and
-- `reserveMediaKey` runs the same expiry before its insert so a key recovers on
-- the next attempt instead of waiting for the 03:00 run.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
ALTER TABLE public.media_key_reservations
  DROP CONSTRAINT media_key_reservations_object_key_unique;
CREATE UNIQUE INDEX media_key_reservations_object_key_unique
  ON public.media_key_reservations USING btree (object_key)
  WHERE status <> 'expired';
CREATE OR REPLACE FUNCTION indicate_private.retention_sweep()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $$
DECLARE v_total integer := 0; v_count integer; v_started timestamptz := now();
BEGIN
  DELETE FROM public.org_invitations WHERE ((accepted_at IS NOT NULL AND accepted_at < now() - interval '90 days') OR (accepted_at IS NULL AND expires_at < now() - interval '90 days')) AND NOT indicate_private.is_org_held(org_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('org_invitations', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.webhook_replay_claims WHERE expires_at < now() AND (organization_id IS NULL OR NOT indicate_private.is_org_held(organization_id));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('webhook_replay_claims', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.object_cleanup_tasks WHERE status = 'completed' AND updated_at < now() - interval '90 days' AND NOT indicate_private.is_org_held(organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('object_cleanup_tasks', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.invalidation_tasks WHERE status IN ('completed', 'failed') AND updated_at < now() - interval '90 days' AND NOT indicate_private.is_org_held(organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('invalidation_tasks', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.publication_transition_receipts r
   WHERE r.created_at < now() - interval '90 days'
     AND NOT indicate_private.is_org_held(r.organization_id)
     AND NOT EXISTS (
       SELECT 1 FROM public.publication_transition_receipts latest
        WHERE latest.organization_id = r.organization_id
          AND latest.job_id = r.job_id
          AND (latest.created_at, latest.id) > (r.created_at, r.id)
     );
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('publication_transition_receipts', v_count, v_started, now());
  v_total := v_total + v_count;
  UPDATE public.media_key_reservations AS reservation
     SET status = 'expired', updated_at = now()
   WHERE reservation.status IN ('reserved', 'occupied')
     AND reservation.expires_at < now()
     AND NOT EXISTS (
       SELECT 1 FROM public.media AS asset
        WHERE asset.organization_id = reservation.organization_id
          AND asset.object_key = reservation.object_key
     )
     AND NOT indicate_private.is_org_held(reservation.organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('media_key_reservations', v_count, v_started, now());
  v_total := v_total + v_count;
  RETURN v_total;
END;
$$;
SELECT indicate_private.retention_sweep();
DO $$
DECLARE
  blocking integer;
  expired integer;
  leaked integer;
  index_def text;
BEGIN
  SELECT count(*) INTO blocking
    FROM public.media_key_reservations
   WHERE status IN ('reserved', 'occupied') AND expires_at < now();
  IF blocking > 0 THEN
    RAISE EXCEPTION 'reservation_expiry_incomplete: % reservation(s) past their deadline still block their key', blocking;
  END IF;
  SELECT count(*) INTO expired FROM public.media_key_reservations WHERE status = 'expired';
  IF expired < 1 THEN
    RAISE EXCEPTION 'reservation_expiry_incomplete: the stuck reservation was not expired';
  END IF;
  SELECT count(*) INTO leaked
    FROM public.media_key_reservations AS reservation
    JOIN public.media AS asset
      ON asset.organization_id = reservation.organization_id
     AND asset.object_key = reservation.object_key
   WHERE reservation.status = 'expired';
  IF leaked > 0 THEN
    RAISE EXCEPTION 'reservation_expiry_unsafe: % expired reservation(s) already produced a media row', leaked;
  END IF;
  SELECT indexdef INTO index_def FROM pg_indexes
   WHERE schemaname = 'public' AND indexname = 'media_key_reservations_object_key_unique';
  IF index_def IS NULL OR index_def NOT ILIKE '%WHERE%' THEN
    RAISE EXCEPTION 'reservation_expiry_incomplete: the object key index still blocks an expired row';
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (189, 'media_reservation_expiry', 'sha256:10e7e403a200f46e0d8f5c4698d1f62daf654cb740f7290ed4eb62bc053d7202');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('2b4646473ccd2c55e5dfa499b06181fe392317feb4297de5a005c9c08b50ed6a', 1790408400000);

-- ----------------------------------------------------------------------
-- 20260925230000_refactor_residue_cleanup
-- ----------------------------------------------------------------------
-- Purge the residue the hierarchy refactor left behind.
--
-- Four tables still carried rows the refactor made meaningless. Nothing reads
-- them for delivery, so each DELETE is behaviour-neutral; this migration also
-- adds the one sweep rule that stops the worst of them from growing back.
--
-- 1. `litigation_holds`: one row from 2026-09-07 whose own reason reads "uji
--    fungsi hold pasca-migrasi v79 (segera dilepas)" and which was released
--    twenty seconds after it was created. A released rehearsal hold is inert,
--    but a compliance ledger should not carry test rows. Only released holds
--    older than thirty days are removed, so an active freeze can never be
--    deleted by this migration.
-- 2. `cache_bypasses`: 114 rows with `bypass = false`, seeded when the network
--    had 114 sites. `readBypassed()` already treats a missing row as "not
--    bypassed", so these rows carry no information, and the 3224 portals the
--    refactor added have no row at all. The table was left describing a network
--    that no longer exists.
-- 3. `domain_activation_attempts`: one failed attempt from 2026-09-13 whose
--    site is now active and activated. The failure is historical noise; the 68
--    completed attempts for live sites are the real activation trail and stay.
-- 4. `media_key_reservations`: 72 rows marked `used` whose object key never
--    produced a `media` row, so each one claims an upload authorization with no
--    artifact behind it. `retention_sweep` now deletes the same shape after a
--    seven-day grace, because a reservation turns into media within seconds and
--    anything older is a ghost.
--
-- Deliberately kept, with the reason:
--   * `audit_logs` is insert-only, hash-chained, and exported to WORM daily;
--     deleting rows would break the chain and the compliance export.
--   * The 104 `site-logo` and 104 `site-favicon` rows are byte-identical today,
--     but they are the per-brand slots a real asset replaces. Collapsing them
--     would make "replace the logo for this brand only" impossible.
--   * The 37 provinces without portals, the nine archived publisher records,
--     the parked Drill Expire organization, the migration ledger, and the one
--     real user are states, not residue.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DELETE FROM public.litigation_holds
 WHERE released_at IS NOT NULL
   AND created_at < now() - interval '30 days';
DELETE FROM public.cache_bypasses WHERE NOT bypass;
DELETE FROM public.domain_activation_attempts AS attempt
 WHERE attempt.status = 'failed'
   AND EXISTS (
     SELECT 1 FROM public.sites AS site
      WHERE site.id = attempt.site_id
        AND site.status = 'active'
        AND site.activation_state = 'active'
   );
DELETE FROM public.media_key_reservations AS reservation
 WHERE reservation.status = 'used'
   AND reservation.created_at < now() - interval '7 days'
   AND NOT EXISTS (
     SELECT 1 FROM public.media AS asset
      WHERE asset.organization_id = reservation.organization_id
        AND asset.object_key = reservation.object_key
   );
CREATE OR REPLACE FUNCTION indicate_private.retention_sweep()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $$
DECLARE v_total integer := 0; v_count integer; v_started timestamptz := now();
BEGIN
  DELETE FROM public.org_invitations WHERE ((accepted_at IS NOT NULL AND accepted_at < now() - interval '90 days') OR (accepted_at IS NULL AND expires_at < now() - interval '90 days')) AND NOT indicate_private.is_org_held(org_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('org_invitations', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.webhook_replay_claims WHERE expires_at < now() AND (organization_id IS NULL OR NOT indicate_private.is_org_held(organization_id));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('webhook_replay_claims', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.object_cleanup_tasks WHERE status = 'completed' AND updated_at < now() - interval '90 days' AND NOT indicate_private.is_org_held(organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('object_cleanup_tasks', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.invalidation_tasks WHERE status IN ('completed', 'failed') AND updated_at < now() - interval '90 days' AND NOT indicate_private.is_org_held(organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('invalidation_tasks', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.publication_transition_receipts r
   WHERE r.created_at < now() - interval '90 days'
     AND NOT indicate_private.is_org_held(r.organization_id)
     AND NOT EXISTS (
       SELECT 1 FROM public.publication_transition_receipts latest
        WHERE latest.organization_id = r.organization_id
          AND latest.job_id = r.job_id
          AND (latest.created_at, latest.id) > (r.created_at, r.id)
     );
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('publication_transition_receipts', v_count, v_started, now());
  v_total := v_total + v_count;
  UPDATE public.media_key_reservations AS reservation
     SET status = 'expired', updated_at = now()
   WHERE reservation.status IN ('reserved', 'occupied')
     AND reservation.expires_at < now()
     AND NOT EXISTS (
       SELECT 1 FROM public.media AS asset
        WHERE asset.organization_id = reservation.organization_id
          AND asset.object_key = reservation.object_key
     )
     AND NOT indicate_private.is_org_held(reservation.organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_total := v_total + v_count;
  DELETE FROM public.media_key_reservations AS reservation
   WHERE reservation.status = 'used'
     AND reservation.updated_at < now() - interval '7 days'
     AND NOT EXISTS (
       SELECT 1 FROM public.media AS asset
        WHERE asset.organization_id = reservation.organization_id
          AND asset.object_key = reservation.object_key
     )
     AND NOT indicate_private.is_org_held(reservation.organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_total := v_total + v_count;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('media_key_reservations', v_count, v_started, now());
  RETURN v_total;
END;
$$;
DO $$
DECLARE
  leftover_holds integer;
  leftover_bypasses integer;
  leftover_failures integer;
  leftover_ghosts integer;
  settings_without_site integer;
  sites_without_settings integer;
  dangling_media integer;
  broken_chains integer;
BEGIN
  SELECT count(*) INTO leftover_holds FROM public.litigation_holds
   WHERE released_at IS NOT NULL AND created_at < now() - interval '30 days';
  IF leftover_holds > 0 THEN
    RAISE EXCEPTION 'refactor_residue_left: % released litigation hold(s) older than 30 days', leftover_holds;
  END IF;
  SELECT count(*) INTO leftover_bypasses FROM public.cache_bypasses WHERE NOT bypass;
  IF leftover_bypasses > 0 THEN
    RAISE EXCEPTION 'refactor_residue_left: % inert cache bypass row(s)', leftover_bypasses;
  END IF;
  SELECT count(*) INTO leftover_failures
    FROM public.domain_activation_attempts AS attempt
    JOIN public.sites AS site ON site.id = attempt.site_id
   WHERE attempt.status = 'failed' AND site.status = 'active' AND site.activation_state = 'active';
  IF leftover_failures > 0 THEN
    RAISE EXCEPTION 'refactor_residue_left: % failed activation attempt(s) for a live portal', leftover_failures;
  END IF;
  SELECT count(*) INTO leftover_ghosts
    FROM public.media_key_reservations AS reservation
   WHERE reservation.status = 'used'
     AND reservation.updated_at < now() - interval '7 days'
     AND NOT EXISTS (
       SELECT 1 FROM public.media AS asset
        WHERE asset.organization_id = reservation.organization_id
          AND asset.object_key = reservation.object_key
     );
  IF leftover_ghosts > 0 THEN
    RAISE EXCEPTION 'refactor_residue_left: % used reservation(s) without a media row', leftover_ghosts;
  END IF;
  SELECT count(*) INTO sites_without_settings FROM public.sites AS site
   WHERE NOT EXISTS (SELECT 1 FROM public.site_settings AS settings
                      WHERE settings.organization_id = site.organization_id AND settings.site_id = site.id);
  SELECT count(*) INTO settings_without_site FROM public.site_settings AS settings
   WHERE NOT EXISTS (SELECT 1 FROM public.sites AS site
                      WHERE site.id = settings.site_id AND site.organization_id = settings.organization_id);
  IF sites_without_settings > 0 OR settings_without_site > 0 THEN
    RAISE EXCEPTION 'refactor_residue_broke_portals: % site(s) without settings, % setting(s) without a site',
      sites_without_settings, settings_without_site;
  END IF;
  SELECT count(*) INTO dangling_media FROM public.site_settings AS settings
   WHERE (settings.default_media_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.media AS asset WHERE asset.id = settings.default_media_id))
      OR (settings.logo_media_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.media AS asset WHERE asset.id = settings.logo_media_id))
      OR (settings.favicon_media_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.media AS asset WHERE asset.id = settings.favicon_media_id));
  IF dangling_media > 0 THEN
    RAISE EXCEPTION 'refactor_residue_broke_portals: % site setting(s) point at a missing asset', dangling_media;
  END IF;
  SELECT count(*) INTO broken_chains FROM public.sites AS site
   WHERE site.parent_site_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.sites AS parent
                      WHERE parent.id = site.parent_site_id
                        AND parent.organization_id = site.organization_id
                        AND parent.domain_id = site.domain_id);
  IF broken_chains > 0 THEN
    RAISE EXCEPTION 'refactor_residue_broke_portals: % derived portal(s) lost their parent', broken_chains;
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (190, 'refactor_residue_cleanup', 'sha256:3d91f78a7de2dc76ab00e409ed32756567762dfa3fa5e77f99a491fcb1f0d1dd');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('68b33327ce5c126c0486cae9d99cab1c120dcda79814730e1e6ff7d8024a47f7', 1790412000000);

-- ----------------------------------------------------------------------
-- 20260925240000_retire_release_governance_tables
-- ----------------------------------------------------------------------
-- Drop the retired runtime-config release governance tables.
--
-- A column-by-column audit of the live database against the application found
-- five tables that no code touches at all: not a Drizzle query, not a raw SQL
-- string, not a trigger, not a view, and not a function in `public` or
-- `indicate_private`. They are the release manifest, the domain-zone mapping,
-- the parity evidence, the backfill run accounting, and the seed run ledger,
-- which together implemented a manifest-driven cutover process that
-- `shared_deployment_config` plus `runtime_config_revisions` replaced.
--
-- All five hold zero rows, and they form a closed foreign-key cluster: the
-- three children reference the manifest with ON DELETE CASCADE and nothing
-- outside the cluster points at any of them. The guard below refuses the drop
-- if any of that is no longer true, so the migration is safe to replay and
-- fails loudly rather than silently losing a row.
--
-- The definitions stay in `20260903000000_core_schema.sql`, so the mechanism can
-- be rebuilt from history if a future release ever needs manifest-driven
-- cutover again.
--
-- What deliberately stays: `runtime_config_revisions`,
-- `runtime_config_audit_logs`, and `runtime_config_invalidation_intents` are
-- live (8, 1, and 2 rows) and read by the runtime-config path; the moderation
-- and privacy decision columns are reserved for features that are not wired
-- yet; `audit_logs.prev_hash` belongs to the database-side hash chain.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DO $$
DECLARE
  manifests integer;
  zones integer;
  parity integer;
  backfills integer;
  seeds integer;
  foreign_refs integer;
BEGIN
  SELECT count(*) INTO manifests FROM public.runtime_config_release_manifests;
  SELECT count(*) INTO zones FROM public.runtime_config_release_domain_zones;
  SELECT count(*) INTO parity FROM public.runtime_config_parity_evidence;
  SELECT count(*) INTO backfills FROM public.runtime_config_backfill_runs;
  SELECT count(*) INTO seeds FROM public.seed_runs;
  IF manifests + zones + parity + backfills + seeds > 0 THEN
    RAISE EXCEPTION
      'retired_tables_not_empty: manifests=% zones=% parity=% backfills=% seeds=%',
      manifests, zones, parity, backfills, seeds;
  END IF;
  SELECT count(*) INTO foreign_refs
    FROM pg_constraint
   WHERE confrelid IN (
     'public.runtime_config_release_manifests'::regclass,
     'public.runtime_config_release_domain_zones'::regclass,
     'public.runtime_config_parity_evidence'::regclass,
     'public.runtime_config_backfill_runs'::regclass,
     'public.seed_runs'::regclass
   );
  IF foreign_refs > 3 THEN
    RAISE EXCEPTION 'retired_tables_still_referenced: % foreign key(s) point at the retired cluster', foreign_refs;
  END IF;
END;
$$;
DROP TABLE public.runtime_config_release_domain_zones;
DROP TABLE public.runtime_config_parity_evidence;
DROP TABLE public.runtime_config_backfill_runs;
DROP TABLE public.runtime_config_release_manifests;
DROP TABLE public.seed_runs;
DROP TYPE public.seed_run_status;
DO $$
DECLARE
  survivors integer;
BEGIN
  SELECT count(*) INTO survivors
    FROM pg_class
   WHERE relkind = 'r'
     AND relnamespace = 'public'::regnamespace
     AND relname IN (
       'runtime_config_release_manifests', 'runtime_config_release_domain_zones',
       'runtime_config_parity_evidence', 'runtime_config_backfill_runs', 'seed_runs'
     );
  IF survivors > 0 THEN
    RAISE EXCEPTION 'retired_tables_survived: % table(s) still present', survivors;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace
              WHERE n.nspname = 'public' AND t.typname = 'seed_run_status') THEN
    RAISE EXCEPTION 'retired_tables_survived: seed_run_status type still present';
  END IF;
  IF to_regclass('public.runtime_config_revisions') IS NULL
     OR to_regclass('public.runtime_config_audit_logs') IS NULL
     OR to_regclass('public.runtime_config_invalidation_intents') IS NULL THEN
    RAISE EXCEPTION 'retired_tables_broke_live_config: a live runtime-config table went missing';
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (191, 'retire_release_governance_tables', 'sha256:4c80e8e3a6f6c1e51b4852aa20b50f8b3de812e6afd083811d13dfbaaa23c4e1');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('46d745927e063d10f14a737d1018e439e9689f757cfb30775761490c983994f6', 1790415600000);

-- ----------------------------------------------------------------------
-- 20260926010000_reconcile_author_newsroom_profile
-- ----------------------------------------------------------------------
-- Reproduce the newsroom author profile that migration 187 applied out of band.
--
-- Production carries a ledger row 187 named `author_newsroom_profile` whose SQL
-- was never committed to this repository. It left no schema object behind; its
-- entire effect is the newsroom author row: on 2026-09-25 15:29 UTC it wrote the
-- editorial policy into `bio`, pointed `avatar_url` at the brand mark, set
-- `website_url`, and moved the row to version 3. A database built from
-- `bootstrap/indicate-schema.sql` therefore ends up without that content while
-- production has it, and the checksum of 187 can never be matched because only
-- the digest survived.
--
-- The checksum stays untouched: rewriting a ledger row to match a file nobody
-- wrote would falsify the record. Instead this forward migration states the
-- effect explicitly and idempotently, so a fresh environment converges on the
-- same author profile. On production it matches zero rows and costs nothing: the
-- UPDATE is guarded by `IS DISTINCT FROM`, so no version churn on a row that is
-- already correct.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
UPDATE public.authors AS author
   SET bio = 'Tim redaksi Indicate menghimpun, memverifikasi, dan menyunting laporan yang dikirim oleh lembaga pemasyarakatan, balai pemasyarakatan, dan rumah tahanan di seluruh jaringan, sebelum dimuat pada portal mitra. Setiap naskah disusun dari sumber resmi yang dapat ditelusuri, lalu melalui dua tahap pemeriksaan: verifikasi faktual terhadap dokumen sumber, dan penyuntingan bahasa, struktur, serta konsistensi nama lembaga. Redaksi menolak naskah yang memuat klaim tanpa rujukan, tidak mencantumkan data pribadi yang tidak berkaitan dengan kepentingan publik, dan menyiarkan setiap perubahan isi sebagai koreksi terbuka. Naskah yang belum dinyatakan lolos verifikasi tidak pernah dipublikasikan. Pembaca dapat menyampaikan konfirmasi, tanggapan, atau permintaan koreksi melalui kanal resmi masing-masing portal mitra.',
       avatar_url = '/brand/indicate-mark.svg',
       website_url = 'https://indicate.website',
       version = author.version + 1,
       updated_at = now()
 WHERE author.display_name = 'Redaksi'
   AND author.organization_id = (SELECT id FROM public.organizations WHERE kind = 'operator')
   AND (author.bio IS DISTINCT FROM 'Tim redaksi Indicate menghimpun, memverifikasi, dan menyunting laporan yang dikirim oleh lembaga pemasyarakatan, balai pemasyarakatan, dan rumah tahanan di seluruh jaringan, sebelum dimuat pada portal mitra. Setiap naskah disusun dari sumber resmi yang dapat ditelusuri, lalu melalui dua tahap pemeriksaan: verifikasi faktual terhadap dokumen sumber, dan penyuntingan bahasa, struktur, serta konsistensi nama lembaga. Redaksi menolak naskah yang memuat klaim tanpa rujukan, tidak mencantumkan data pribadi yang tidak berkaitan dengan kepentingan publik, dan menyiarkan setiap perubahan isi sebagai koreksi terbuka. Naskah yang belum dinyatakan lolos verifikasi tidak pernah dipublikasikan. Pembaca dapat menyampaikan konfirmasi, tanggapan, atau permintaan koreksi melalui kanal resmi masing-masing portal mitra.'
     OR author.avatar_url IS DISTINCT FROM '/brand/indicate-mark.svg'
     OR author.website_url IS DISTINCT FROM 'https://indicate.website');
DO $$
DECLARE
  reconciled integer;
  operator_orgs integer;
BEGIN
  SELECT count(*) INTO operator_orgs FROM public.organizations WHERE kind = 'operator';
  IF operator_orgs <> 1 THEN
    RAISE EXCEPTION 'newsroom_profile_ambiguous: % operator organizations, expected exactly 1', operator_orgs;
  END IF;
  SELECT count(*) INTO reconciled FROM public.authors AS author
   WHERE author.display_name = 'Redaksi'
     AND author.organization_id = (SELECT id FROM public.organizations WHERE kind = 'operator')
     AND author.bio IS NOT NULL
     AND author.avatar_url = '/brand/indicate-mark.svg'
     AND author.website_url = 'https://indicate.website';
  IF reconciled <> 1 THEN
    RAISE EXCEPTION 'newsroom_profile_missing: % reconciled newsroom author row(s), expected 1', reconciled;
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (192, 'reconcile_author_newsroom_profile', 'sha256:df9dae7264942a084e1840ce2a2baac313fa1c4e9619766805ed7a9dbffdeecb');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('db2540a3804e49229f0ad0d392b21b2e4ad45f42b1b1b2ce03912cb2f4874611', 1790419200000);

-- ----------------------------------------------------------------------
-- 20260926020000_purge_drill_litigation_hold
-- ----------------------------------------------------------------------
-- Remove the drill litigation hold from the legal register.
--
-- `litigation_holds` exists to freeze erasure and retention for an organization
-- under a legal hold. Its single row was a rehearsal: the reason reads "uji
-- fungsi hold pasca-migrasi v79 (segera dilepas)", it was created 2026-09-07
-- 11:03:42 UTC and released twenty seconds later at 11:04:02, and it names the
-- Drill Expire organization, which is itself a parked test tenant. `is_org_held`
-- only counts unreleased holds, so the row blocks nothing; it is pure rehearsal
-- residue sitting in a compliance register, which is the one place a leftover
-- test row is least defensible.
--
-- The delete is targeted by id, reason, and release state rather than by a broad
-- age rule, so a real hold can never be caught by it: an active hold has
-- `released_at IS NULL` and does not match. The guard asserts both that the drill
-- row is gone and that no unreleased hold was touched.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DELETE FROM public.litigation_holds
 WHERE id = '977b207c-23d6-4a50-9ac3-3ab1586cbbbc'::uuid
   AND reason = 'Uji fungsi hold pasca-migrasi v79 (segera dilepas).'
   AND released_at IS NOT NULL;
DO $$
DECLARE
  drill_left integer;
  active_holds integer;
BEGIN
  SELECT count(*) INTO drill_left FROM public.litigation_holds
   WHERE reason ILIKE '%uji fungsi hold%';
  IF drill_left > 0 THEN
    RAISE EXCEPTION 'drill_hold_left: % rehearsal hold row(s) still in the register', drill_left;
  END IF;
  SELECT count(*) INTO active_holds FROM public.litigation_holds WHERE released_at IS NULL;
  IF active_holds > 0 THEN
    RAISE EXCEPTION 'drill_hold_touched: % hold(s) are still in force and must stay', active_holds;
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (193, 'purge_drill_litigation_hold', 'sha256:b2a881c116059abded1badb58972a60dc4475002770275624b99a5767707627b');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('ac6b1d72fb89b9cb9be6c09fabe761caefbd96a482a8e0ae38f30cd906b6af35', 1790422800000);

-- ----------------------------------------------------------------------
-- 20260926030000_purge_superseded_media_reservations
-- ----------------------------------------------------------------------
-- Retire superseded upload reservations on a realistic clock.
--
-- A media upload is authorized for minutes: the stuck reservation found earlier
-- was created 03:45:33 and expired at 03:55:33 the same minute. A `used`
-- reservation whose object key never produced a `media` row is therefore an
-- abandoned attempt, and the only question is how patient the cleanup should be.
-- Seven days was chosen first and turned out to be longer than the real data
-- needed: 54 reservations from 2026-09-19 still sat inside that window while
-- every one of them targeted an apex portal that already carries both a logo and
-- a favicon, so the upload had plainly been superseded. Three days is roughly
-- four hundred times the authorization window and still leaves no room for a
-- genuine in-flight upload.
--
-- The sweep rule is restated with the same three-day grace so the scheduled job
-- and this migration can never disagree. The guard asserts that no `media` row
-- lost its object key and that the live portal graph is untouched.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DELETE FROM public.media_key_reservations AS reservation
 WHERE reservation.status = 'used'
   AND reservation.updated_at < now() - interval '3 days'
   AND NOT indicate_private.is_org_held(reservation.organization_id)
   AND NOT EXISTS (
     SELECT 1 FROM public.media AS asset
      WHERE asset.organization_id = reservation.organization_id
        AND asset.object_key = reservation.object_key
   );
CREATE OR REPLACE FUNCTION indicate_private.retention_sweep()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $$
DECLARE v_total integer := 0; v_count integer; v_started timestamptz := now();
BEGIN
  DELETE FROM public.org_invitations WHERE ((accepted_at IS NOT NULL AND accepted_at < now() - interval '90 days') OR (accepted_at IS NULL AND expires_at < now() - interval '90 days')) AND NOT indicate_private.is_org_held(org_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('org_invitations', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.webhook_replay_claims WHERE expires_at < now() AND (organization_id IS NULL OR NOT indicate_private.is_org_held(organization_id));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('webhook_replay_claims', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.object_cleanup_tasks WHERE status = 'completed' AND updated_at < now() - interval '90 days' AND NOT indicate_private.is_org_held(organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('object_cleanup_tasks', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.invalidation_tasks WHERE status IN ('completed', 'failed') AND updated_at < now() - interval '90 days' AND NOT indicate_private.is_org_held(organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('invalidation_tasks', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.publication_transition_receipts r
   WHERE r.created_at < now() - interval '90 days'
     AND NOT indicate_private.is_org_held(r.organization_id)
     AND NOT EXISTS (
       SELECT 1 FROM public.publication_transition_receipts latest
        WHERE latest.organization_id = r.organization_id
          AND latest.job_id = r.job_id
          AND (latest.created_at, latest.id) > (r.created_at, r.id)
     );
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('publication_transition_receipts', v_count, v_started, now());
  v_total := v_total + v_count;
  UPDATE public.media_key_reservations AS reservation
     SET status = 'expired', updated_at = now()
   WHERE reservation.status IN ('reserved', 'occupied')
     AND reservation.expires_at < now()
     AND NOT EXISTS (
       SELECT 1 FROM public.media AS asset
        WHERE asset.organization_id = reservation.organization_id
          AND asset.object_key = reservation.object_key
     )
     AND NOT indicate_private.is_org_held(reservation.organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_total := v_total + v_count;
  DELETE FROM public.media_key_reservations AS reservation
   WHERE reservation.status = 'used'
     AND reservation.updated_at < now() - interval '3 days'
     AND NOT EXISTS (
       SELECT 1 FROM public.media AS asset
        WHERE asset.organization_id = reservation.organization_id
          AND asset.object_key = reservation.object_key
     )
     AND NOT indicate_private.is_org_held(reservation.organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_total := v_total + v_count;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('media_key_reservations', v_count, v_started, now());
  RETURN v_total;
END;
$$;
DO $$
DECLARE
  ghosts integer;
  settings_orphan_media integer;
  portals_without_settings integer;
  index_def text;
BEGIN
  SELECT count(*) INTO ghosts FROM public.media_key_reservations
   WHERE status = 'used'
     AND NOT EXISTS (SELECT 1 FROM public.media AS asset
                      WHERE asset.organization_id = media_key_reservations.organization_id
                        AND asset.object_key = media_key_reservations.object_key);
  IF ghosts > 0 THEN
    RAISE EXCEPTION 'reservation_ghosts_left: % used reservation(s) without a media row', ghosts;
  END IF;
  SELECT count(*) INTO settings_orphan_media FROM public.site_settings AS settings
   WHERE (settings.default_media_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.media AS asset WHERE asset.id = settings.default_media_id))
      OR (settings.logo_media_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.media AS asset WHERE asset.id = settings.logo_media_id))
      OR (settings.favicon_media_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.media AS asset WHERE asset.id = settings.favicon_media_id));
  IF settings_orphan_media > 0 THEN
    RAISE EXCEPTION 'reservation_ghosts_broke_media: % site setting(s) point at a missing asset', settings_orphan_media;
  END IF;
  SELECT count(*) INTO portals_without_settings FROM public.sites AS site
   WHERE NOT EXISTS (SELECT 1 FROM public.site_settings AS settings
                      WHERE settings.organization_id = site.organization_id AND settings.site_id = site.id);
  IF portals_without_settings > 0 THEN
    RAISE EXCEPTION 'reservation_ghosts_broke_portals: % site(s) lost their settings', portals_without_settings;
  END IF;
  SELECT indexdef INTO index_def FROM pg_indexes
   WHERE schemaname = 'public' AND indexname = 'media_key_reservations_object_key_unique';
  IF index_def IS NULL OR index_def NOT ILIKE '%WHERE%' THEN
    RAISE EXCEPTION 'reservation_ghosts_broke_guard: the object key index is no longer partial';
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (194, 'purge_superseded_media_reservations', 'sha256:d4af963f6d9a87235c453cbe2d2207f2ed2aad563a1e7369f6644f7450b8595c');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('8ae50186a792ae32f4dff73ed52acc192a224a86374c60783295114b90056bef', 1790426400000);

-- ----------------------------------------------------------------------
-- 20260926040000_drop_vestigial_replay_outcome_reference
-- ----------------------------------------------------------------------
-- Drop the vestigial replay outcome reference.
--
-- `webhook_replay_claims` keeps the replay outcome in three places that are all
-- live: the `outcome` payload, `processed_at`, and `outcome_ready_at`, which
-- `prepareReplayOutcome`, `finalizeReplay`, and `completeReplay` maintain and
-- `mapRawClaim` reads. `outcome_reference` was left over from an earlier design
-- where the outcome lived somewhere else and the row only pointed at it. Nothing
-- writes it, nothing reads it, and all existing rows hold NULL, so it is a
-- column that only ever invites the question "what is this for?".
--
-- The guard asserts the column is empty before dropping it, so a future write
-- path cannot be silently truncated, and it re-checks that the replay surface
-- the application actually reads still resolves.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DO $$
DECLARE
  populated integer;
BEGIN
  SELECT count(*) INTO populated FROM public.webhook_replay_claims
   WHERE outcome_reference IS NOT NULL AND btrim(outcome_reference) <> '';
  IF populated > 0 THEN
    RAISE EXCEPTION 'outcome_reference_not_vestigial: % replay claim(s) carry a value', populated;
  END IF;
END;
$$;
ALTER TABLE public.webhook_replay_claims DROP COLUMN outcome_reference;
DO $$
DECLARE
  survivors integer;
  unreadable integer;
BEGIN
  SELECT count(*) INTO survivors
    FROM information_schema.columns
   WHERE table_schema = 'public' AND table_name = 'webhook_replay_claims'
     AND column_name = 'outcome_reference';
  IF survivors > 0 THEN
    RAISE EXCEPTION 'outcome_reference_survived: the column is still present';
  END IF;
  SELECT count(*) INTO unreadable
    FROM public.webhook_replay_claims AS claim
   WHERE claim.pending_status IS NOT NULL
     AND (claim.processed_at IS NULL OR claim.outcome_ready_at IS NULL);
  IF unreadable > 0 THEN
    RAISE EXCEPTION 'outcome_reference_broke_replays: % terminal claim(s) lost their outcome timestamps', unreadable;
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (195, 'drop_vestigial_replay_outcome_reference', 'sha256:73d3ecea6d1f35dd4318dff75908a2a871aea08532f07b5a082a84b8882c90f6');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('81bb2693e585a48a7e8cf37ea9652f9f2fe7d77377f40aa44c0c39a2e9dbc9d0', 1790430000000);

-- ----------------------------------------------------------------------
-- 20260926050000_retain_only_active_cache_bypasses
-- ----------------------------------------------------------------------
-- Keep only the cache bypasses that are actually active.
--
-- `readBypassed()` treats a missing row as "not bypassing", so once an
-- invalidation completes its row carries no information: the table ends up with
-- one row per portal forever, describing the default state. That is the same
-- shape the refactor residue cleanup found in migration 190, and every onboarding
-- wave brings it back: the ten newest tenants alone produced 330 rows, of which
-- 190 were live `invalidation_pending` bypasses and the rest had already
-- completed and were pure noise.
--
-- The sweep therefore deletes rows whose bypass is off and leaves every active
-- bypass untouched, which turns the table back into what the delivery read
-- actually asks: "is this portal bypassing right now". A portal with an
-- in-flight invalidation keeps its bypass until the reconciler finishes, because
-- the guard refuses the whole migration if any such portal would lose it.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
CREATE OR REPLACE FUNCTION indicate_private.retention_sweep()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $$
DECLARE v_total integer := 0; v_count integer; v_started timestamptz := now();
BEGIN
  DELETE FROM public.org_invitations WHERE ((accepted_at IS NOT NULL AND accepted_at < now() - interval '90 days') OR (accepted_at IS NULL AND expires_at < now() - interval '90 days')) AND NOT indicate_private.is_org_held(org_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('org_invitations', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.webhook_replay_claims WHERE expires_at < now() AND (organization_id IS NULL OR NOT indicate_private.is_org_held(organization_id));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('webhook_replay_claims', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.object_cleanup_tasks WHERE status = 'completed' AND updated_at < now() - interval '90 days' AND NOT indicate_private.is_org_held(organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('object_cleanup_tasks', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.invalidation_tasks WHERE status IN ('completed', 'failed') AND updated_at < now() - interval '90 days' AND NOT indicate_private.is_org_held(organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('invalidation_tasks', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.cache_bypasses AS bypass
   WHERE NOT bypass.bypass
     AND NOT indicate_private.is_org_held(bypass.organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('cache_bypasses', v_count, v_started, now());
  v_total := v_total + v_count;
  DELETE FROM public.publication_transition_receipts r
   WHERE r.created_at < now() - interval '90 days'
     AND NOT indicate_private.is_org_held(r.organization_id)
     AND NOT EXISTS (
       SELECT 1 FROM public.publication_transition_receipts latest
        WHERE latest.organization_id = r.organization_id
          AND latest.job_id = r.job_id
          AND (latest.created_at, latest.id) > (r.created_at, r.id)
     );
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('publication_transition_receipts', v_count, v_started, now());
  v_total := v_total + v_count;
  UPDATE public.media_key_reservations AS reservation
     SET status = 'expired', updated_at = now()
   WHERE reservation.status IN ('reserved', 'occupied')
     AND reservation.expires_at < now()
     AND NOT EXISTS (
       SELECT 1 FROM public.media AS asset
        WHERE asset.organization_id = reservation.organization_id
          AND asset.object_key = reservation.object_key
     )
     AND NOT indicate_private.is_org_held(reservation.organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_total := v_total + v_count;
  DELETE FROM public.media_key_reservations AS reservation
   WHERE reservation.status = 'used'
     AND reservation.updated_at < now() - interval '3 days'
     AND NOT EXISTS (
       SELECT 1 FROM public.media AS asset
        WHERE asset.organization_id = reservation.organization_id
          AND asset.object_key = reservation.object_key
     )
     AND NOT indicate_private.is_org_held(reservation.organization_id);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_total := v_total + v_count;
  INSERT INTO public.retention_runs(category, purged_count, started_at, finished_at) VALUES ('media_key_reservations', v_count, v_started, now());
  RETURN v_total;
END;
$$;
SELECT indicate_private.retention_sweep();
DO $$
DECLARE
  inert_left integer;
  bypass_lost integer;
BEGIN
  SELECT count(*) INTO inert_left FROM public.cache_bypasses WHERE NOT bypass;
  IF inert_left > 0 THEN
    RAISE EXCEPTION 'cache_bypass_inert_left: % completed bypass row(s) survived', inert_left;
  END IF;
  SELECT count(*) INTO bypass_lost
    FROM public.invalidation_tasks AS task
   WHERE task.status IN ('pending', 'processing')
     AND EXISTS (
       SELECT 1 FROM public.cache_bypasses AS bypass
        WHERE bypass.site_id = task.site_id AND NOT bypass.bypass
     );
  IF bypass_lost > 0 THEN
    RAISE EXCEPTION 'cache_bypass_unsafe: % portal(s) with in-flight invalidation lost their bypass', bypass_lost;
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (196, 'retain_only_active_cache_bypasses', 'sha256:64a9a5d54884e2bb0481b728178fc95170b4f7949d5b04ce84a3ad69b29be2fb');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('b63dab6baa073b874498cf18ff3661808a1d52ccd32b73578d33559557e46e1d', 1790433600000);

-- ----------------------------------------------------------------------
-- 20260926060000_arm_schema_gate
-- ----------------------------------------------------------------------
-- Arm the schema gate at this release.
--
-- The gate has been disarmed since it was built, and the database has already
-- drifted once because of it: ledger row 187 (`author_newsroom_profile`) was
-- applied outside this repository, and nothing at boot noticed. A disarmed gate
-- cannot catch the next one either.
--
-- `assertSchemaGate` fails closed when a `required_version` row exists and the
-- applied ledger does not satisfy it, so arming is a real promise: every
-- environment that boots against this database must have migration 197 applied.
-- The version is this migration itself, written in the same transaction as the
-- ledger row, so a fresh environment reaches it by replaying the journal and an
-- already-promoted environment passes the moment the transaction commits.
--
-- A refusal now records its own evidence: the gate writes `actual_version`
-- beside `required_version` and names the ledger's `applied_at` in the error, so
-- the incident answer exists without guesswork. Adjust the floor in a later
-- migration when a release needs it; `AGENTS.md` leaves the arming policy to
-- the release.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
INSERT INTO public.migration_gate_events (id, required_version, actual_version, status)
VALUES (gen_random_uuid(), 197, 197, 'completed'::public.task_status);
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (197, 'arm_schema_gate', 'sha256:86a1caf7bce165a57f12c87038f96431ef55adbced88332a8c9062c9721e0531');
DO $$
DECLARE
  armed integer;
  floor integer;
  applied integer;
BEGIN
  SELECT count(*) INTO armed FROM public.migration_gate_events
   WHERE required_version = 197 AND status = 'completed';
  IF armed <> 1 THEN
    RAISE EXCEPTION 'schema_gate_not_armed: % arming row(s) for 197', armed;
  END IF;
  SELECT max(version) INTO applied FROM public.indicate_schema_migrations;
  SELECT required_version INTO floor FROM public.migration_gate_events
   ORDER BY checked_at DESC, id DESC LIMIT 1;
  IF applied IS NULL OR applied < floor THEN
    RAISE EXCEPTION 'schema_gate_would_block_boot: applied=% required=%', applied, floor;
  END IF;
END;
$$;

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('f28b32dc1650780735eca8bae05f4eeed4155bf6ba8e66b90c42795dc53504d9', 1790437200000);

-- ----------------------------------------------------------------------
-- 20260926120000_runtime_config_environment_cast
-- ----------------------------------------------------------------------
-- Cast the runtime environment inside the runtime-config mutation functions.
--
-- Every function that commits a runtime-config or site-settings change read the
-- environment from `current_setting('app.environment', true)`, which is `text`,
-- and inserted it straight into the `runtime_config_environment` columns of
-- `runtime_config_revisions`, `runtime_config_audit_logs`, and
-- `runtime_config_invalidation_intents`. Those columns have been the enum since
-- the runtime-config core migration, so each call raised 42804 on its first
-- insert and rolled the whole change back. The admin runtime-config surface
-- could not commit anything, and every production config change so far had to
-- bypass it with hand-written SQL.
--
-- The repair reuses the idiom `20260915020000_media_policy_allow_ico` already
-- established, including its `production` default for an unset setting, and then
-- asserts that no uncast read survives anywhere in the schema, so this migration
-- fails closed instead of leaving a partial repair behind.
--
-- Rewriting the stored source keeps exactly one definition of each function in
-- the catalog; restating eight bodies by hand here would let them drift from the
-- migrations that created them.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DO $$
DECLARE
  target regprocedure;
  patched integer := 0;
BEGIN
  FOR target IN
    SELECT function_entry.oid::regprocedure
      FROM pg_proc AS function_entry
      JOIN pg_namespace AS nsp ON nsp.oid = function_entry.pronamespace
     WHERE nsp.nspname = 'indicate_private'
       AND function_entry.prosrc LIKE '%current_setting(''app.environment'', true)%'
       AND function_entry.prosrc NOT LIKE '%::public.runtime_config_environment%'
  LOOP
    EXECUTE replace(
      pg_get_functiondef(target),
      'current_setting(''app.environment'', true)',
      'COALESCE(NULLIF(current_setting(''app.environment'', true), ''''), ''production'')::public.runtime_config_environment'
    );
    patched := patched + 1;
  END LOOP;
  IF patched = 0 THEN
    RAISE EXCEPTION 'runtime_config_environment_cast_missing: no uncast environment read found';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM pg_proc AS function_entry
      JOIN pg_namespace AS nsp ON nsp.oid = function_entry.pronamespace
     WHERE nsp.nspname = 'indicate_private'
       AND function_entry.prosrc LIKE '%current_setting(''app.environment'', true)%'
       AND function_entry.prosrc NOT LIKE '%::public.runtime_config_environment%'
  ) THEN
    RAISE EXCEPTION 'runtime_config_environment_cast_incomplete: an uncast environment read remains';
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (198, 'runtime_config_environment_cast', 'sha256:2aa56704731ce39b6c2f82eafd3f9f3e33347881a57cd76a78cb2511aaf4c858');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('3f09a7f362d99b27e7a46f48706ea51e698306ac9baa3ea64c9ff316d61ab30f', 1790448000000);

-- ----------------------------------------------------------------------
-- 20260926130000_publication_fanout_throughput
-- ----------------------------------------------------------------------
-- Raise publication throughput to the network fan-out ceiling.
--
-- A publication job drains at most `batch_size` targets per worker invocation
-- and the worker only runs on a cron, so those two are the entire throughput
-- budget: the configured 50-second function deadline was never the binding
-- constraint, because ten targets finish in a few seconds and the run stops on
-- the batch, not on the clock. Publishing to every active portal therefore
-- needed about 37 hours at the previous settings, while the same sweep costs
-- roughly one to three dollars of Vercel usage and the cron change adds about
-- 27 cents a month, so there is nothing to trade away for speed here.
--
-- The three values keep a full batch inside one invocation while the lease
-- stays longer than the run it protects, so a worker that dies mid-batch is
-- repaired by reconciliation instead of losing its fence:
--
--   batch_size               10 -> 100   the column's own upper bound
--   lease_seconds            30 -> 300   longer than any run this size implies
--   function_deadline_seconds 50 -> 100  still under the route's 120 s ceiling
--
-- The lease is deliberately the maximum the column allows. Recovery of a crashed
-- job is bounded by the reconciliation cron rather than by the lease length, so
-- a longer lease costs nothing and removes the `stale_fence` failure mode that a
-- hundred-target run would otherwise hit at the old 30 seconds.
--
-- The bookkeeping below mirrors `mutate_runtime_config_publication_policy`
-- because that function cannot be used yet: migration 198 removed its enum
-- defect, and its remaining defect is inserting an explicit value into the
-- `GENERATED ALWAYS AS IDENTITY` revision column. Recording the change here
-- keeps a full audit trail and invalidation intent, and keeps a fresh
-- environment on the same throughput as production.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DO $$
DECLARE
  resulting integer;
  revision bigint;
BEGIN
  UPDATE public.publication_policy AS policy
     SET batch_size = 100, lease_seconds = 300, function_deadline_seconds = 100,
         version = version + 1, updated_at = now()
   WHERE policy.singleton_key = 'singleton'
  RETURNING policy.version INTO resulting;
  IF resulting IS NULL THEN
    RAISE EXCEPTION 'publication_policy_missing: singleton row not found';
  END IF;
  INSERT INTO public.runtime_config_revisions (environment, committed_at, mutation_kind)
  VALUES ('production', now(), 'publication_policy')
  RETURNING version INTO revision;
  INSERT INTO public.runtime_config_audit_logs (
    id, organization_id, actor_type, actor_id, environment, action, target_type,
    target_id, expected_version, resulting_version, changed_fields, outcome, request_id
  ) VALUES (
    gen_random_uuid(), NULL, 'migration', NULL, 'production', 'update', 'publication_policy',
    NULL, resulting - 1, resulting,
    ARRAY['batch_size', 'lease_seconds', 'function_deadline_seconds'],
    'succeeded', 'migration:199:publication_fanout_throughput'
  );
  INSERT INTO public.runtime_config_invalidation_intents (
    id, runtime_revision, environment, partition_kind, status, attempts, next_attempt_at
  ) VALUES (gen_random_uuid(), revision, 'production', 'policy', 'pending', 0, now());
END;
$$;
DO $$
DECLARE
  policy public.publication_policy%ROWTYPE;
BEGIN
  SELECT * INTO policy FROM public.publication_policy WHERE singleton_key = 'singleton';
  IF policy.batch_size <> 100 OR policy.lease_seconds <> 300 OR policy.function_deadline_seconds <> 100 THEN
    RAISE EXCEPTION 'publication_policy_throughput_not_applied: %', policy.version;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.runtime_config_audit_logs
     WHERE target_type = 'publication_policy' AND actor_type = 'migration'
       AND request_id = 'migration:199:publication_fanout_throughput'
  ) THEN
    RAISE EXCEPTION 'publication_policy_audit_missing';
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (199, 'publication_fanout_throughput', 'sha256:20f3be28302c3fc53999bd1390f70e00f61ec431930a5839d8a9cf7561fd76f0');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('85eb4bf6d569d54628edb497f7602317546c46b913653a71a0da16e4543e7bad', 1790452800000);

-- ----------------------------------------------------------------------
-- 20260926140000_social_warm_once
-- ----------------------------------------------------------------------
-- Warm each public article URL for social scrapers exactly once, at first publish.
--
-- Every mutation that touched an article used to hand its URL back to Meta's
-- scrape backend, so one editorial edit — or one publisher rename, which fans
-- out to every article that publisher owns — spent app quota to re-scrape a URL
-- Meta had already cached for about thirty days. The marker below replaces that
-- fan-out with one scrape per URL for the lifetime of the article.
--
-- `article_sites` is one row per (article, site) pair, so it is the row that owns
-- one public URL, `https://{hostname}/{slug}`. Keying the marker there rather
-- than on the article matters: a site assignment publishes a brand-new URL for an
-- article that is not new at all, and that URL still needs its one scrape.
--
-- The backfill marks every already-published row. Articles live before this
-- migration keep whatever Meta already cached instead of spending one quota unit
-- each the first time somebody edits them, and it keeps the due set equal to
-- "published since the migration", which is what the warmer drains.
--
-- `due_social_warm_targets` reads that set oldest-first and `mark_social_warm_targets`
-- fills it, so a warm that fails or is cut off by the dispatch budget stays due
-- and is retried on the next minute rather than being lost.
--
-- The partial index holds only published, unmarked rows, which is empty in
-- steady state, so the due query costs an index probe and the marker adds one
-- nullable column and no table bloat.

ALTER TABLE public.article_sites ADD COLUMN social_warmed_at timestamptz;

UPDATE public.article_sites
   SET social_warmed_at = published_at
 WHERE state = 'published' AND published_at IS NOT NULL AND social_warmed_at IS NULL;

CREATE INDEX article_sites_social_warm_due_idx
  ON public.article_sites (published_at, id)
  WHERE social_warmed_at IS NULL AND state = 'published';

-- Oldest-due first: a URL whose warm failed or was cut off is retried before
-- newer URLs, and LIMIT caps one dispatch regardless of backlog size.
CREATE OR REPLACE FUNCTION indicate_private.due_social_warm_targets(p_limit integer)
RETURNS TABLE (article_site_id uuid, url text)
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $function$
  SELECT target.id, 'https://' || host.normalized_hostname || '/' || article.slug
    FROM public.article_sites AS target
    JOIN public.articles AS article
      ON article.organization_id = target.organization_id AND article.id = target.article_id
    JOIN public.sites AS host
      ON host.organization_id = target.organization_id AND host.id = target.site_id
   WHERE target.social_warmed_at IS NULL
     AND target.state = 'published'
     AND target.active
     AND host.status = 'active'
   ORDER BY target.published_at, target.id
   LIMIT greatest(1, least(p_limit, 200));
$function$;
REVOKE ALL ON FUNCTION indicate_private.due_social_warm_targets(integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION indicate_private.due_social_warm_targets(integer) TO indicate_runtime;

-- Fills only NULL markers, so a concurrent dispatcher that already recorded the
-- same URL is not overwritten and the call is idempotent.
CREATE OR REPLACE FUNCTION indicate_private.mark_social_warm_targets(p_article_site_ids uuid[], p_now timestamptz)
RETURNS integer
LANGUAGE sql
VOLATILE SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $function$
  WITH filled AS (
    UPDATE public.article_sites AS target
       SET social_warmed_at = p_now
     WHERE target.id = ANY (p_article_site_ids)
       AND target.social_warmed_at IS NULL
    RETURNING 1
  )
  SELECT count(*)::integer FROM filled;
$function$;
REVOKE ALL ON FUNCTION indicate_private.mark_social_warm_targets(uuid[], timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION indicate_private.mark_social_warm_targets(uuid[], timestamptz) TO indicate_runtime;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.article_sites
     WHERE state = 'published' AND published_at IS NOT NULL AND social_warmed_at IS NULL
  ) THEN
    RAISE EXCEPTION 'social_warm_backfill_incomplete';
  END IF;
END;
$$;

-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (200, 'social_warm_once', 'sha256:066f8e73c35430da3cf8cf7352f975756dbfd5e8ae59123676c2a91217b66eca');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('d63130b400c688842d2473dbfad039290cab82c3b5ba6115b3b8ef50b64b1307', 1790456400000);

-- ----------------------------------------------------------------------
-- 20260926150000_runtime_config_revision_identity
-- ----------------------------------------------------------------------
-- Let the revision identity assign its own value.
--
-- Migration 198 removed the enum defect that stopped every runtime-config
-- mutation at its first insert. The next statement was just as unreachable: each
-- function read the revisions sequence with nextval() and then inserted that
-- value into `version`, which has been `bigint GENERATED ALWAYS AS IDENTITY`
-- since the runtime-config core migration. Postgres refuses an explicit value
-- there (428C9), so the functions still could not commit anything, including
-- `mutate_runtime_config_media_policy`, the one mutation the dashboard exposes
-- through `POST /api/dashboard/runtime-config`.
--
-- The repair drops the sequence read, lets the identity column assign the
-- revision, and reads it back with RETURNING, which is also what the
-- invalidation intent has to point at. No other part of the bodies changes.
--
-- The transform is four literal string replacements rather than a rewrite, so
-- each one is checkable on its own: the sequence read goes, `version` leaves the
-- column list, the `v_revision` value leaves the VALUES tuple, and the statement
-- gains its RETURNING clause. The loop then asserts that no function reads the
-- sequence explicitly and that every function writing a revision reads it back,
-- so this migration fails closed instead of leaving a half-repaired catalog.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DO $$
DECLARE
  target regprocedure;
  mutation_kind text;
  definition text;
  patched integer := 0;
  expected integer;
BEGIN
  SELECT count(*) INTO expected
    FROM pg_proc AS function_entry
    JOIN pg_namespace AS nsp ON nsp.oid = function_entry.pronamespace
   WHERE nsp.nspname = 'indicate_private'
     AND function_entry.prosrc LIKE '%INSERT INTO public.runtime_config_revisions%';
  IF expected = 0 THEN
    RAISE EXCEPTION 'runtime_config_revision_identity_missing: no function writes a revision';
  END IF;
  FOR target, mutation_kind IN
    SELECT function_entry.oid::regprocedure,
           substring(function_entry.prosrc FROM 'now\(\), ''([a-z_]+)''\);')
      FROM pg_proc AS function_entry
      JOIN pg_namespace AS nsp ON nsp.oid = function_entry.pronamespace
     WHERE nsp.nspname = 'indicate_private'
       AND function_entry.prosrc LIKE '%INSERT INTO public.runtime_config_revisions%'
  LOOP
    IF mutation_kind IS NULL THEN
      RAISE EXCEPTION 'runtime_config_revision_identity_unreadable: % revision statement not recognized', target;
    END IF;
    definition := pg_get_functiondef(target);
    definition := replace(
      definition,
      'v_revision := nextval(pg_get_serial_sequence(''public.runtime_config_revisions'', ''version''));',
      ''
    );
    definition := replace(
      definition,
      'INSERT INTO public.runtime_config_revisions (version, environment, committed_at, mutation_kind)',
      'INSERT INTO public.runtime_config_revisions (environment, committed_at, mutation_kind)'
    );
    definition := replace(definition, '(v_revision, ', '(');
    definition := replace(
      definition,
      ', now(), ''' || mutation_kind || ''');',
      ', now(), ''' || mutation_kind || ''') RETURNING version INTO v_revision;'
    );
    definition := replace(definition, 'VALUES ( COALESCE', 'VALUES (COALESCE');
    EXECUTE definition;
    patched := patched + 1;
  END LOOP;
  IF patched <> expected THEN
    RAISE EXCEPTION 'runtime_config_revision_identity_partial: patched % of % revision writers', patched, expected;
  END IF;
  IF EXISTS (
    SELECT 1
      FROM pg_proc AS function_entry
      JOIN pg_namespace AS nsp ON nsp.oid = function_entry.pronamespace
     WHERE nsp.nspname = 'indicate_private'
       AND function_entry.prosrc LIKE '%nextval(pg_get_serial_sequence(''public.runtime_config_revisions''%'
  ) THEN
    RAISE EXCEPTION 'runtime_config_revision_identity_incomplete: an explicit revision sequence read remains';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM pg_proc AS function_entry
      JOIN pg_namespace AS nsp ON nsp.oid = function_entry.pronamespace
     WHERE nsp.nspname = 'indicate_private'
       AND function_entry.prosrc LIKE '%INSERT INTO public.runtime_config_revisions (version,%'
  ) THEN
    RAISE EXCEPTION 'runtime_config_revision_identity_incomplete: a revision insert still names the identity column';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM pg_proc AS function_entry
      JOIN pg_namespace AS nsp ON nsp.oid = function_entry.pronamespace
     WHERE nsp.nspname = 'indicate_private'
       AND function_entry.prosrc LIKE '%INSERT INTO public.runtime_config_revisions%'
       AND function_entry.prosrc NOT LIKE '%RETURNING version INTO v_revision;%'
  ) THEN
    RAISE EXCEPTION 'runtime_config_revision_identity_incomplete: a revision writer does not read its revision back';
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (201, 'runtime_config_revision_identity', 'sha256:b6bd83c9a3822a9caa08f14d4bb73a88da144338a7ef4477b7038283bc4a8d86');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('223631c84a0ff66b7ef974bafa9f7dc77907e99048b31ab07a83e54b65d7fa4f', 1790467200000);

-- ----------------------------------------------------------------------
-- 20260926160000_site_settings_manage_permission
-- ----------------------------------------------------------------------
-- Make `site_settings.manage` a real organization permission.
--
-- `indicate_private.mutate_site_settings` guards on `site_settings.manage`, but
-- that permission was never sanctioned. It is absent from
-- `permission_definitions`, its only row in `permissions` was platform-scoped,
-- and `permission_has_tenant` resolves a tenant permission through
-- memberships, roles, and role_permissions only. A platform-scoped row can never
-- satisfy that check, and no grant existed anywhere either, so the function was
-- unreachable for every actor.
--
-- The permission becomes organization-scoped, one row per organization that
-- already manages sites, granted to exactly the roles that hold `site.manage`.
-- That is the set the dashboard already authorizes to edit site settings, so the
-- function and the dashboard share one authority instead of introducing a second
-- one over the same table.
--
-- The platform-scoped row is removed last, and only after checking that nothing
-- references it: it cannot match the tenant check, so keeping it would only
-- mislead the next reader.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
INSERT INTO public.permission_definitions (scope, name, description, sort_order)
VALUES ('organization'::public.permission_scope, 'site_settings.manage', 'Manage site settings', 28)
ON CONFLICT (scope, name) DO NOTHING;
INSERT INTO public.permissions (id, organization_id, name, scope, description, created_at)
SELECT gen_random_uuid(), source.organization_id, 'site_settings.manage',
       'organization'::public.permission_scope, 'Manage site settings', now()
  FROM public.permissions AS source
 WHERE source.name = 'site.manage'
   AND source.organization_id IS NOT NULL
ON CONFLICT DO NOTHING;
INSERT INTO public.role_permissions (organization_id, role_id, permission_id)
SELECT granted.organization_id, granted.role_id, target.id
  FROM public.role_permissions AS granted
  JOIN public.permissions AS source
    ON source.id = granted.permission_id AND source.name = 'site.manage'
  JOIN public.permissions AS target
    ON target.organization_id = granted.organization_id AND target.name = 'site_settings.manage'
ON CONFLICT DO NOTHING;
DO $$
DECLARE
  phantom integer;
BEGIN
  SELECT count(*) INTO phantom
    FROM public.permissions AS candidate
   WHERE candidate.name = 'site_settings.manage'
     AND candidate.organization_id IS NULL
     AND (
       EXISTS (SELECT 1 FROM public.role_permissions AS grant_row WHERE grant_row.permission_id = candidate.id)
       OR EXISTS (SELECT 1 FROM public.platform_user_permissions AS grant_row WHERE grant_row.permission_id = candidate.id)
     );
  IF phantom > 0 THEN
    RAISE EXCEPTION 'site_settings_permission_referenced: % platform-scoped row(s) still granted', phantom;
  END IF;
  DELETE FROM public.permissions
   WHERE name = 'site_settings.manage' AND organization_id IS NULL;
END;
$$;
DO $$
DECLARE
  orgs_without integer;
  roles_without integer;
  platform_left integer;
BEGIN
  SELECT count(*) INTO orgs_without
    FROM (SELECT DISTINCT organization_id FROM public.permissions WHERE name = 'site.manage') AS managed
   WHERE NOT EXISTS (
     SELECT 1 FROM public.permissions AS scoped
      WHERE scoped.name = 'site_settings.manage' AND scoped.organization_id = managed.organization_id
   );
  IF orgs_without > 0 THEN
    RAISE EXCEPTION 'site_settings_permission_incomplete: % organization(s) missing it', orgs_without;
  END IF;
  SELECT count(*) INTO roles_without
    FROM public.role_permissions AS granted
    JOIN public.permissions AS source ON source.id = granted.permission_id AND source.name = 'site.manage'
   WHERE NOT EXISTS (
     SELECT 1
       FROM public.role_permissions AS mirrored
       JOIN public.permissions AS target ON target.id = mirrored.permission_id
      WHERE mirrored.organization_id = granted.organization_id
        AND mirrored.role_id = granted.role_id
        AND target.name = 'site_settings.manage'
   );
  IF roles_without > 0 THEN
    RAISE EXCEPTION 'site_settings_grant_incomplete: % role grant(s) missing it', roles_without;
  END IF;
  SELECT count(*) INTO platform_left
    FROM public.permissions
   WHERE name = 'site_settings.manage' AND organization_id IS NULL;
  IF platform_left > 0 THEN
    RAISE EXCEPTION 'site_settings_permission_phantom_left: % platform-scoped row(s) remain', platform_left;
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (202, 'site_settings_manage_permission', 'sha256:7a6a06fed65423b64d05ee575b5d138e6c3a19d599714ce2bf4ef2b9f4c87273');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('6f94f59164e019cdc55068f4f5b7c85b87a1227465830c127f09a429914e7fa0', 1790470800000);

-- ----------------------------------------------------------------------
-- 20260926170000_site_settings_robots_directive_cast
-- ----------------------------------------------------------------------
-- Cast the robots directive in `mutate_site_settings`.
--
-- The function takes `p_seo_robots_directive` as text and assigns it straight to
-- `site_settings.seo_robots_directive`, which is the `seo_robots_directive` enum.
-- Every call therefore failed with 42804 on the UPDATE, after its permission
-- check had already passed, so the function could never commit a change. This is
-- the same missing-cast defect that migration 198 repaired in the runtime-config
-- functions, on a different column.
--
-- The other columns the function writes match their parameter types, and the
-- revision bookkeeping it shares with the runtime-config functions was repaired
-- by migration 201.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DO $$
DECLARE
  target regprocedure := 'indicate_private.mutate_site_settings(uuid,uuid,uuid,text,text,text,text,text,integer,uuid,integer)'::regprocedure;
  definition text;
  patched integer;
BEGIN
  IF (SELECT prosrc FROM pg_proc WHERE oid = target) NOT LIKE '%seo_robots_directive = p_seo_robots_directive,%' THEN
    RAISE EXCEPTION 'site_settings_robots_cast_missing: uncast assignment not found';
  END IF;
  definition := replace(
    pg_get_functiondef(target),
    'seo_robots_directive = p_seo_robots_directive,',
    'seo_robots_directive = p_seo_robots_directive::public.seo_robots_directive,'
  );
  EXECUTE definition;
  SELECT count(*) INTO patched
    FROM pg_proc
   WHERE oid = target
     AND prosrc LIKE '%seo_robots_directive = p_seo_robots_directive::public.seo_robots_directive,%';
  IF patched <> 1 THEN
    RAISE EXCEPTION 'site_settings_robots_cast_not_applied';
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (203, 'site_settings_robots_directive_cast', 'sha256:9fd351d5ca580214ae541de39d8f5acc3274ecf942d43761dc7e2f337594beb1');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('a98a1077e49431e37db6025fba6d42acd09780ad66ec8e27bbb31fe1e26484ce', 1790474400000);

-- ----------------------------------------------------------------------
-- 20260926180000_audit_chain_head_lock
-- ----------------------------------------------------------------------
-- Serialize the audit hash-chain head so overlapping inserts cannot fork it.
--
-- `indicate_private.audit_chain_fill` read the chain head with
-- `SELECT signature ... ORDER BY seq DESC LIMIT 1 FOR UPDATE`. `FOR UPDATE` locks
-- the row it reads, not the position in that ordering, so two audit inserts that
-- overlap inside the same window could both observe the same head and then write
-- two rows carrying an identical `prev_hash`. The chain forks: the later row's
-- link no longer matches its predecessor's signature, and `audit_verify_chain`
-- reports it.
--
-- Six such forks exist. All are `media.access.authorize` rows written by the
-- system actor between 2026-09-16 and 2026-09-17, each sharing its `prev_hash`
-- with exactly one neighbour. Their payloads and signatures are intact — the
-- HMAC over the stored row still reproduces — so the link is wrong and nothing
-- else is. That makes this an ordering defect rather than data corruption, and
-- it stays invisible until someone reads the chain instead of the rows.
--
-- A transaction-level advisory lock taken before the head read makes the whole
-- read-then-write sequence exclusive across sessions, which is what a single
-- linear chain actually requires. `pg_advisory_xact_lock` is released when the
-- transaction ends, so neither a commit nor a rollback can strand it. Once that
-- lock is held the `FOR UPDATE` is redundant, and dropping it leaves one locking
-- mechanism instead of two that look sufficient but are not.
--
-- The lock lives until the inserting transaction ends, so audit appends now
-- serialize globally rather than per organization. Audit volume is a handful of
-- small rows per operation and the wait is short, which is a fair price for a
-- chain that verifies. Deadlock is still possible in principle if a transaction
-- takes the advisory lock here and then waits on a business-row lock another
-- audit-writing transaction already holds; Postgres detects that and aborts one,
-- so the failure is loud and retryable rather than a silent fork.
--
-- The rows that are already unverifiable stay as they are. Re-signing the chain
-- would turn `audit_verify_chain` green by rewriting the very history these six
-- forks are evidence of, and a chain that verifies because it was re-signed says
-- less than one that verifies and is honest about its past.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
CREATE OR REPLACE FUNCTION indicate_private.audit_chain_fill()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $function$
DECLARE v_prev text; v_key text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('indicate.audit_chain_head'));
  SELECT signature INTO v_prev FROM public.audit_logs ORDER BY seq DESC LIMIT 1;
  NEW.occurred_at := clock_timestamp();
  NEW.prev_hash := v_prev;
  SELECT decrypted_secret INTO v_key FROM vault.decrypted_secrets WHERE name = 'audit_hmac_key' ORDER BY created_at DESC LIMIT 1;
  IF v_key IS NULL THEN
    RAISE EXCEPTION 'audit hmac key missing' USING ERRCODE = '42501';
  END IF;
  NEW.signature := encode(extensions.hmac(indicate_private.audit_chain_input(to_jsonb(NEW), NEW.prev_hash), v_key, 'sha256'), 'hex');
  RETURN NEW;
END
$function$;
DO $$
DECLARE
  body text;
BEGIN
  body := pg_get_functiondef('indicate_private.audit_chain_fill()'::regprocedure);
  IF position('pg_advisory_xact_lock' in body) = 0 THEN
    RAISE EXCEPTION 'audit_chain_head_lock_missing: head is still read without the advisory lock';
  END IF;
  IF position('FOR UPDATE' in upper(body)) > 0 THEN
    RAISE EXCEPTION 'audit_chain_head_lock_redundant: FOR UPDATE still present alongside the advisory lock';
  END IF;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (204, 'audit_chain_head_lock', 'sha256:bbab7baa060fd1a05855aac525b0b049b9075db1332df326e0b495a46e2b3c5d');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('b4b24494492cf9f7bb09ac238eee0d5c4e3fa6a5be91966186c92d9ecb3c3036', 1790478000000);

-- ----------------------------------------------------------------------
-- 20260926190000_publisher_brand_removal
-- ----------------------------------------------------------------------
-- Remove the network's portal brands from `publishers`.
--
-- `publishers` mixed two different subjects. The 118 `correctional_institution`
-- rows are the newsrooms the network actually syndicates: each one owns its own
-- Organization and appears both in the platform organization and in its tenant
-- organization, which is what the affiliation model resolves against. The nine
-- `independent_publisher` rows were something else entirely — Kabar360,
-- Liputan99, Fakta01, Jurnalism, WawasanNusa, and four more. Each of those
-- names is a portal brand, not a newsroom: every one of them is the apex label
-- of 33 rows in `sites` (the bare apex plus 32 city subdomains such as
-- `banjarnegara.kabar360.biz.id`), and each carried the brand logo through
-- `contacts.logoUrl` pointing at the same `media` row that `site_settings`
-- already references as `logo_media_id` for that apex site.
--
-- Reading the dashboard publisher list therefore mixed institutions with the
-- network's own properties, which is why the roster showed archived brand rows
-- interleaved with active institutions and read as one list of publishers.
-- These rows carry no publishing history at all: zero `articles` and zero
-- `official_affiliations` reference them, and `audit_logs` records them only as
-- the `publisher.archive` transition that retired them on 2026-09-22. A brand
-- belongs to `sites` and `site_settings`, which already hold it, so deleting
-- the duplicate publisher row loses no brand information and orphans no media:
-- the `media` rows stay referenced by `site_settings.logo_media_id` and stay
-- reachable through the public brand route.
--
-- The delete is restricted to that exact shape rather than to a name list, so a
-- genuine independent newsroom is never removed by name collision, and the
-- guard block below refuses to run unless every remaining archived
-- `independent_publisher` row without publishing history is a portal brand. If
-- a future independent publisher with articles behind it appears, the predicate
-- stops matching and the guard fails loudly instead of deleting a newsroom.
--
-- `audit_logs` rows are never touched: insert-only by design with daily WORM
-- export (see docs/migrations.md). One `publisher.delete` row is appended per
-- removed brand so the erasure itself is on the record.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DO $$
DECLARE
  pending integer;
  unexplained integer;
BEGIN
  SELECT count(*) INTO pending
    FROM public.publishers AS p
   WHERE p.type = 'independent_publisher'
     AND p.status = 'archived'
     AND NOT EXISTS (SELECT 1 FROM public.articles AS a WHERE a.publisher_id = p.id)
     AND NOT EXISTS (SELECT 1 FROM public.official_affiliations AS o WHERE o.publisher_id = p.id)
     AND EXISTS (
       SELECT 1 FROM public.sites AS s
        WHERE s.organization_id = p.organization_id
          AND s.normalized_hostname ILIKE '%' || lower(p.name) || '%'
     );

  IF pending = 0 THEN
    RAISE EXCEPTION 'publisher_brand_removal_nothing_to_do: no unreferenced archived brand rows remain';
  END IF;

  SELECT count(*) INTO unexplained
    FROM public.publishers AS p
   WHERE p.type = 'independent_publisher'
     AND p.status = 'archived'
     AND NOT EXISTS (SELECT 1 FROM public.articles AS a WHERE a.publisher_id = p.id)
     AND NOT EXISTS (SELECT 1 FROM public.official_affiliations AS o WHERE o.publisher_id = p.id)
     AND NOT EXISTS (
       SELECT 1 FROM public.sites AS s
        WHERE s.organization_id = p.organization_id
          AND s.normalized_hostname ILIKE '%' || lower(p.name) || '%'
     );

  IF unexplained > 0 THEN
    RAISE EXCEPTION 'publisher_brand_removal_ambiguous: % archived rows without publishing history are not portal brands', unexplained;
  END IF;
END;
$$;
WITH removed AS (
  DELETE FROM public.publishers AS p
   WHERE p.type = 'independent_publisher'
     AND p.status = 'archived'
     AND NOT EXISTS (SELECT 1 FROM public.articles AS a WHERE a.publisher_id = p.id)
     AND NOT EXISTS (SELECT 1 FROM public.official_affiliations AS o WHERE o.publisher_id = p.id)
     AND EXISTS (
       SELECT 1 FROM public.sites AS s
        WHERE s.organization_id = p.organization_id
          AND s.normalized_hostname ILIKE '%' || lower(p.name) || '%'
     )
  RETURNING p.organization_id, p.id, p.name, p.attribution_label, p.type
), audited AS (
  INSERT INTO public.audit_logs (
    organization_id, id, actor_type, actor_id, entry_point, action, target_type,
    target_id, outcome, changed_fields, before, request_id
  )
  SELECT organization_id,
         gen_random_uuid(),
         'system'::public.audit_actor_type,
         'migration:publisher_brand_removal',
         'worker'::public.audit_entry_point,
         'publisher.delete',
         'publisher',
         id::text,
         'succeeded'::public.audit_outcome,
         ARRAY['status'],
         jsonb_build_object(
           'id', id,
           'name', name,
           'type', type,
           'attributionLabel', attribution_label,
           'status', 'archived'
         ),
         'migration:205'
    FROM removed
  RETURNING organization_id
)
SELECT count(*) FROM audited;
DO $$
DECLARE
  remaining integer;
  orphaned_media integer;
BEGIN
  SELECT count(*) INTO remaining
    FROM public.publishers AS p
   WHERE p.type = 'independent_publisher'
     AND p.status = 'archived'
     AND NOT EXISTS (SELECT 1 FROM public.articles AS a WHERE a.publisher_id = p.id)
     AND NOT EXISTS (SELECT 1 FROM public.official_affiliations AS o WHERE o.publisher_id = p.id)
     AND EXISTS (
       SELECT 1 FROM public.sites AS s
        WHERE s.organization_id = p.organization_id
          AND s.normalized_hostname ILIKE '%' || lower(p.name) || '%'
     );

  IF remaining <> 0 THEN
    RAISE EXCEPTION 'publisher_brand_removal_incomplete: % mirrored brand rows still present', remaining;
  END IF;

  SELECT count(*) INTO orphaned_media
    FROM public.media AS m
   WHERE NOT EXISTS (SELECT 1 FROM public.site_settings AS s WHERE s.logo_media_id = m.id)
     AND NOT EXISTS (SELECT 1 FROM public.site_settings AS s WHERE s.favicon_media_id = m.id)
     AND NOT EXISTS (SELECT 1 FROM public.site_settings AS s WHERE s.default_media_id = m.id);

  RAISE NOTICE 'publisher_brand_removal_done: unreferenced media rows now %', orphaned_media;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (205, 'publisher_brand_removal', 'sha256:bf26f268c32325f2ca192df55f3d09a7f17a53d3296a980b8a1e286cd7261461');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('e8100322757317b7bce632f9aef9b6297c69b0e2d405e1fa692e07f8e2f4fee2', 1790481600000);

-- ----------------------------------------------------------------------
-- 20260926200000_default_article_category
-- ----------------------------------------------------------------------
-- Seed the default article category for every organization that can publish.
--
-- `articles.category_id` was nullable and the article composer let the field
-- stay empty, so an article could be filed under no category at all. Every
-- consumer degrades on that: the article page drops the category chip and the
-- breadcrumb segment, the nav and the author profile build their category
-- lists from `categorySlug IS NOT NULL` so the article is unreachable from
-- any category page, and the NewsArticle JSON-LD, the OpenGraph `section`, and
-- the RSS `<category>` element are all omitted. An article nobody can browse
-- to and whose structured data is missing is the worst possible filing, and it
-- happened silently.
--
-- The default is `Umum` (slug `umum`). "Lainnya" would have been the obvious
-- alternative, but a fallback that reads as a rubbish bin is one editors start
-- ignoring; `Umum` is the neutral filing label Indonesian newsrooms actually
-- use for material that does not belong to a specific desk.
--
-- The row is seeded per organization rather than globally because categories
-- are tenant data (`categories.organization_id`). Sixty of the sixty-one
-- organizations had no category row at all, so scoping the seed to
-- organizations that own a publisher is what makes a tenant able to file an
-- article at all; `Drill Expire` owns no publisher and gets no category.
--
-- `TenantBusinessService` resolves this slug before writing, so an article can
-- no longer be stored without a category even when an API caller omits the
-- field, and the composer pre-selects it so the choice is visible rather than
-- silent.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
INSERT INTO public.categories (organization_id, id, name, slug, status, version, created_at, updated_at)
SELECT publisher_org.organization_id,
       gen_random_uuid(),
       'Umum',
       'umum',
       'active'::public.record_status,
       1,
       now(),
       now()
  FROM (SELECT DISTINCT organization_id FROM public.publishers) AS publisher_org
  LEFT JOIN public.categories AS existing
    ON existing.organization_id = publisher_org.organization_id
   AND existing.slug = 'umum'
 WHERE existing.id IS NULL;
DO $$
DECLARE
  seeded integer;
  expected integer;
  missing integer;
BEGIN
  SELECT count(*) INTO expected
    FROM (SELECT DISTINCT organization_id FROM public.publishers) AS publisher_org;

  SELECT count(*) INTO seeded
    FROM public.categories
   WHERE slug = 'umum'
     AND status = 'active'
     AND EXISTS (SELECT 1 FROM public.publishers AS p WHERE p.organization_id = categories.organization_id);

  SELECT count(*) INTO missing
    FROM (SELECT DISTINCT organization_id FROM public.publishers) AS publisher_org
   WHERE NOT EXISTS (
     SELECT 1 FROM public.categories AS c
      WHERE c.organization_id = publisher_org.organization_id
        AND c.slug = 'umum'
        AND c.status = 'active'
   );

  IF missing <> 0 THEN
    RAISE EXCEPTION 'default_article_category_missing: % publishing organizations have no active umum category', missing;
  END IF;

  RAISE NOTICE 'default_article_category_done: % seeded, % publishing organizations', seeded, expected;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (206, 'default_article_category', 'sha256:1b33e87699190df9803a5701d9a5b4288e6ec131bb01e9d80396be7616db0846');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('0c2beda581d76609112d6239859fa14f373ea675119e45c5c22fa3bd6eab7d72', 1790485200000);

-- ----------------------------------------------------------------------
-- 20260927020000_moderation_reader_id_qualification
-- ----------------------------------------------------------------------
-- Qualify `public.users.id` in the two moderation readers that declare an
-- `id` output column. PL/pgSQL turns each RETURNS TABLE column into a
-- variable, so the unqualified `WHERE id = p_actor_id` guard resolved against
-- both the output variable and the table column and failed with
-- `42702 column reference "id" is ambiguous`. Both readers therefore raised on
-- every call, which surfaced as `503 Moderation is temporarily unavailable` for
-- the content-report and privacy-ticket queues.
CREATE OR REPLACE FUNCTION indicate_private.content_report_list(p_actor_id uuid)
 RETURNS TABLE(id uuid, org_id uuid, site_id uuid, article_id uuid, reporter_contact text, reason_category text, details text, article_url text, status report_status, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = p_actor_id AND u.status = 'active') THEN
    RAISE EXCEPTION 'active user required' USING ERRCODE = '42501';
  END IF;
  IF indicate_private.permission_has_platform_admin(p_actor_id) THEN
    RETURN QUERY SELECT r.id, r.organization_id, r.site_id, r.article_id, r.reporter_contact, r.reason_category, r.details, r.article_url, r.status, r.created_at
    FROM public.content_reports r ORDER BY r.created_at DESC;
  ELSE
    RETURN QUERY SELECT r.id, r.organization_id, r.site_id, r.article_id, r.reporter_contact, r.reason_category, r.details, r.article_url, r.status, r.created_at
    FROM public.content_reports r JOIN public.memberships m ON m.organization_id = r.organization_id
    WHERE m.user_id = p_actor_id AND m.status = 'active' ORDER BY r.created_at DESC;
  END IF;
END
$function$;
REVOKE ALL ON FUNCTION indicate_private.content_report_list(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION indicate_private.content_report_list(uuid) TO indicate_runtime;

CREATE OR REPLACE FUNCTION indicate_private.privacy_request_list(p_actor_id uuid)
 RETURNS TABLE(id uuid, ticket_number text, org_id uuid, request_type privacy_request_type, details text, status privacy_request_status, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = p_actor_id AND u.status = 'active') THEN
    RAISE EXCEPTION 'active user required' USING ERRCODE = '42501';
  END IF;
  IF indicate_private.permission_has_platform_admin(p_actor_id) THEN
    RETURN QUERY SELECT r.id, r.ticket_number, r.organization_id, r.request_type, r.details, r.status, r.created_at
    FROM public.privacy_requests r ORDER BY r.created_at DESC;
  ELSE
    RETURN QUERY SELECT r.id, r.ticket_number, r.organization_id, r.request_type, r.details, r.status, r.created_at
    FROM public.privacy_requests r JOIN public.memberships m ON m.organization_id = r.organization_id
    WHERE m.user_id = p_actor_id AND m.status = 'active' ORDER BY r.created_at DESC;
  END IF;
END
$function$;
REVOKE ALL ON FUNCTION indicate_private.privacy_request_list(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION indicate_private.privacy_request_list(uuid) TO indicate_runtime;

INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (207, 'moderation_reader_id_qualification', 'sha256:daf314952676e7c32157144b7b1dd074562ad6bc81db20b8a7da1ee742e7c076');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('ad65050321a254c0c54d8189cb3a8a243747a9176979a6766de173660bd179ab', 1790488800000);

-- ----------------------------------------------------------------------
-- 20260927030000_derived_portal_title_rebuild
-- ----------------------------------------------------------------------
-- Rebuild derived portal titles from the intact apex title.
--
-- Migration 20260925120000 built each regional and city portal title by
-- concatenating its area label onto the apex seo_default_title, then truncating
-- the result to 60 characters. The apex title it concatenated was itself already
-- cut at a hard character boundary, so the derived titles compounded the cut and
-- ended mid-phrase: "Boyolali - NawalaPerkara - Liputan yang memberi gambaran".
-- The missing tail is unrecoverable from the stored value, so this rebuilds the
-- string from the apex title as it stands today and cuts only on a word boundary.

with apex_titles as (
  select distinct
    s.organization_id,
    s.domain_id,
    coalesce(nullif(btrim(apex_settings.seo_default_title), ''), apex_settings.name) as apex_title
  from public.sites s
  join public.sites apex
    on apex.organization_id = s.organization_id
   and apex.domain_id = s.domain_id
   and apex.site_level = 'apex'
  join public.site_settings apex_settings on apex_settings.site_id = apex.id
  where s.site_level in ('region', 'city')
),
rebuilt as (
  select
    ss.site_id,
    case
      when length(coalesce(r.name, '') || ' - ' || a.apex_title) <= 60
        then coalesce(r.name, '') || ' - ' || a.apex_title
      else btrim(regexp_replace(left(coalesce(r.name, '') || ' - ' || a.apex_title, 60), '\s+\S*$', ''))
    end as title
  from public.site_settings ss
  join public.sites s on s.id = ss.site_id
  join apex_titles a on a.organization_id = s.organization_id and a.domain_id = s.domain_id
  join public.regions r on r.id = s.region_id
  where s.site_level in ('region', 'city')
)
update public.site_settings ss
set
  seo_default_title = rebuilt.title,
  version = ss.version + 1,
  updated_at = now()
from rebuilt
where ss.site_id = rebuilt.site_id
  and ss.seo_default_title is distinct from rebuilt.title;

INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (208, 'derived_portal_title_rebuild', 'sha256:2e13bc93f45e8a353c2346537c4361626a4afd44f9988c8d5d906fe56b611a74');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('b077fb24cb6e6b32d8020fd778bc5f6b2fa49f9932c2ade2051464c4f124d082', 1790492400000);

-- ----------------------------------------------------------------------
-- 20260927130000_drop_unpublished_auto_assignments
-- ----------------------------------------------------------------------
-- Drop the assignment rows that the removed automatic distribution created.
--
-- article.create used to write one article_sites row per active portal in the
-- organization. Delivery only ever reads rows in the published state, and
-- publication is the operation that decides which portals an article reaches,
-- so every one of those rows was invisible, unused, and pure write amplification.
-- On the main tenant 30 articles left 132,660 rows behind, and each editorial
-- write also enqueued a cache invalidation per portal, which is what pushed the
-- invalidation queue past half a million rows and the database over its size
-- allowance.
--
-- A row is dead when it is still queued, carries no publication timestamp, and
-- no publication job ever targeted it. Anything a job touched, or that has been
-- published, is left alone so in-flight and live work survives. The delete runs
-- in batches so it stays inside a statement timeout on a large backlog.

DO $migration$
DECLARE
  passes integer := 0;
  batch_size constant integer := 2000;
BEGIN
  LOOP
    DELETE FROM public.article_sites
    WHERE id IN (
      SELECT candidate.id
      FROM public.article_sites AS candidate
      WHERE candidate.state = 'queued'
        AND candidate.published_at IS NULL
        AND NOT EXISTS (
          SELECT 1 FROM public.publishing_job_targets AS target
          WHERE target.article_site_id = candidate.id
        )
      ORDER BY candidate.id
      LIMIT batch_size
    );
    passes := passes + 1;
    EXIT WHEN passes > 10000;
  END LOOP;
END
$migration$;

INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (209, 'drop_unpublished_auto_assignments', 'sha256:09a60347a6fe4fc18565194e26bca74f3b2cfc5f99528f3ddf20a8324c24b7fb');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('4a439bb6cb61919e4599750374df9c3badff56b8c36eeb70efcb5588e2ecae52', 1790499600000);

-- ----------------------------------------------------------------------
-- 20260927200000_social_warm_cooldown
-- ----------------------------------------------------------------------
-- Give the social warm a cooldown so one unreachable target cannot hold the queue.
--
-- `due_social_warm_targets` is oldest-first and `SocialWarmer` marks a target
-- only after Meta accepted it, so a target that never succeeds is due again on
-- every dispatch forever. On production nothing was ever marked: 4,020 of 4,020
-- published `article_sites` rows still carried a NULL `social_warmed_at`, all
-- 64 slots of every tick went to the same 2026-07-28 batch, and a newly
-- published article sat at position 4,021 behind a window it could never enter.
--
-- Two columns break that: `social_warm_attempts` counts failed attempts and
-- `social_warm_next_attempt_at` parks the target until a cooldown elapses, so a
-- permanently failing URL falls out of the oldest-first window instead of
-- starving everything newer. The cooldown doubles from 30s and caps at 7 days,
-- which both spreads Meta's quota and lets a genuinely fixed deployment resume
-- without a manual reset.
--
-- The existing backlog is parked for a week rather than warmed. Meta caches a
-- URL for about 30 days and spends several units of an app-wide quota per
-- scrape, so 4,020 pre-scrape calls would burn that quota on links first
-- published in July. Rows published after this migration start with a NULL
-- cooldown and are due on the next dispatch, so warming proceeds forward only.

ALTER TABLE public.article_sites
  ADD COLUMN social_warm_attempts integer NOT NULL DEFAULT 0,
  ADD COLUMN social_warm_next_attempt_at timestamp with time zone;

ALTER TABLE public.article_sites
  ADD CONSTRAINT article_sites_social_warm_attempts_nonnegative CHECK (social_warm_attempts >= 0);

CREATE OR REPLACE FUNCTION indicate_private.social_warm_cooldown(p_attempts integer)
 RETURNS interval
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT make_interval(secs => LEAST(604800, 30 * (2 ^ LEAST(GREATEST(p_attempts, 1) - 1, 15))))
$function$;

CREATE OR REPLACE FUNCTION indicate_private.due_social_warm_targets(p_limit integer)
 RETURNS TABLE(article_site_id uuid, url text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $function$
  SELECT target.id, 'https://' || host.normalized_hostname || '/' || article.slug
    FROM public.article_sites AS target
    JOIN public.articles AS article
      ON article.organization_id = target.organization_id AND article.id = target.article_id
    JOIN public.sites AS host
      ON host.organization_id = target.organization_id AND host.id = target.site_id
   WHERE target.social_warmed_at IS NULL
     AND target.state = 'published'
     AND target.active
     AND host.status = 'active'
     AND (target.social_warm_next_attempt_at IS NULL OR target.social_warm_next_attempt_at <= now())
   ORDER BY target.social_warm_next_attempt_at NULLS FIRST, target.published_at, target.id
   LIMIT greatest(1, least(p_limit, 200));
$function$;

CREATE OR REPLACE FUNCTION indicate_private.mark_social_warm_attempts(p_article_site_ids uuid[], p_now timestamptz)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $function$
DECLARE
  touched integer;
BEGIN
  UPDATE public.article_sites AS target
     SET social_warm_attempts = target.social_warm_attempts + 1,
         social_warm_next_attempt_at = p_now + indicate_private.social_warm_cooldown(target.social_warm_attempts + 1),
         updated_at = p_now
   WHERE target.id = ANY(p_article_site_ids)
     AND target.social_warmed_at IS NULL;
  GET DIAGNOSTICS touched = ROW_COUNT;
  RETURN touched;
END
$function$;

DROP INDEX IF EXISTS public.article_sites_social_warm_due_idx;

CREATE INDEX article_sites_social_warm_due_idx
  ON public.article_sites (social_warm_next_attempt_at NULLS FIRST, published_at, id)
  WHERE social_warmed_at IS NULL AND state = 'published';

ANALYZE public.article_sites;

UPDATE public.article_sites
   SET social_warm_attempts = 1,
       social_warm_next_attempt_at = now() + interval '7 days'
 WHERE social_warmed_at IS NULL
   AND state = 'published'
   AND social_warm_next_attempt_at IS NULL;

INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (210, 'social_warm_cooldown', 'sha256:bed6cd96936947333e2f4603d9091d439693eb0c5e06718f345e20215e056c50');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('f839abb021c7cde156fe1473efe70961be54d4486ce98d23be3d778efc965d7b', 1790503200000);

-- ----------------------------------------------------------------------
-- 20260928020000_purge_unreferenced_media_placeholders
-- ----------------------------------------------------------------------
-- Purge the unreferenced media placeholders that accumulated in the private R2
-- bucket, and schedule the object deletes through the platform's own durable
-- queue instead of deleting bytes out of band.
--
-- Three groups, all `active` in `media` and all unreferenced by every
-- reference surface the schema has: `site_settings.logo_media_id`,
-- `site_settings.favicon_media_id`, `site_settings.default_media_id`,
-- `articles.lead_media_id`, `article_sites.custom_image_media_id`, and the
-- `media:{uuid}` embeds inside `articles.body_json`.
--
-- 1. `site-default` (68 rows). Two generations exist per site: the
--    `og-default` card the backfill wrote, and the `site-default` card the
--    tenant application wrote when the brand gradient landed. `delivery` serves
--    `settings.default_media_id` and falls back to a static asset when that
--    pointer is null, so the second generation was never rendered. Nothing
--    re-points to it either: `propagateBrandMedia` only rewrites portals that
--    already pointed at the previous id, it never picks a replacement from the
--    remaining active rows.
--
-- 2. `article-inline` (1 row). An upload that completed after the body was
--    already re-pointed elsewhere, so no embed references it. Its predecessor
--    at the same body position is already `archived` and already purged.
--
-- 3. `organization-asset` (59 rows). The 2026-09-24 backfill copied one file,
--    `24-logo-kemenimipas.png`, into every tenant Organization. All 60 copies
--    share a single ETag, so 59 of them are pure duplication, and none is
--    referenced: organization assets become publicly visible only through a
--    published copy that references them. The platform Organization's own copy
--    is excluded and stays `active`, because that one is the operator's own
--    brand asset rather than a tenant placeholder.
--
-- Four of the 59 rows are the reason this migration also matters: their object
-- was uploaded under a corrupted `o/{org}` prefix spliced from the neighbouring
-- Organization id, so the row points at a key that was never written while the
-- bytes sit under a prefix no row can address. Archiving them is still correct
-- — the placeholder has no bytes to serve — and the media-versus-R2
-- reconciliation added in the same release reports both halves of that class
-- from now on.
--
-- The predicate is structural: it names purposes and reference surfaces, never
-- a media id, an object key, or a filename token, so it cannot drift into
-- deleting a row that became referenced after the count below was taken. The
-- guard refuses to run unless the shape is still exactly 68 / 1 / 59, and the
-- second guard re-runs the same predicate afterwards and fails if a single row
-- survives. Both run in the transaction that archives the rows, so a reference
-- that appears between the two statements rolls the whole migration back.
--
-- Object bytes are not deleted here. Each archived row gets an
-- `object_cleanup_tasks` row, which the existing reconciler claims
-- (`indicate_private.claim_media_cleanup_tasks`, cron every five minutes), and
-- which deletes the object and records the outcome. That keeps the intent in
-- Postgres before the external effect, keeps the delete resumable and
-- idempotent, and avoids a hand-run `DeleteObject` that no later reconciliation
-- would notice. `archiveMedia` in the publishing repository never enqueued this
-- task, which is why unreferenced rows outlived their bytes until now; that
-- gap is closed in the same release.
--
-- `audit_logs` rows are never touched: insert-only by design with daily WORM
-- export (see docs/migrations.md). One `media.archive` row is appended per
-- archived row so the purge is on the record.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DO $$
DECLARE
  pending integer;
  site_default_rows integer;
  article_inline_rows integer;
  organization_asset_rows integer;
  platform_rows integer;
BEGIN
  SELECT count(*),
         count(*) FILTER (WHERE purpose = 'site-default'),
         count(*) FILTER (WHERE purpose = 'article-inline'),
         count(*) FILTER (WHERE purpose = 'organization-asset')
    INTO pending, site_default_rows, article_inline_rows, organization_asset_rows
    FROM public.media AS m
   WHERE m.state = 'active'
     AND m.purpose IN ('site-default', 'article-inline', 'organization-asset')
     AND (m.purpose <> 'organization-asset'
          OR m.organization_id <> '7e27727d-b59f-4d24-998e-1bee6eeb3fa0'::uuid)
     AND NOT EXISTS (SELECT 1 FROM public.site_settings AS s
                      WHERE s.logo_media_id = m.id OR s.favicon_media_id = m.id OR s.default_media_id = m.id)
     AND NOT EXISTS (SELECT 1 FROM public.articles AS a WHERE a.lead_media_id = m.id)
     AND NOT EXISTS (SELECT 1 FROM public.article_sites AS x WHERE x.custom_image_media_id = m.id)
     AND NOT EXISTS (SELECT 1 FROM public.articles AS b
                      WHERE b.body_json::text ~ ('media:' || m.id::text || '(?![0-9a-f-])'));

  IF pending <> 128 OR site_default_rows <> 68 OR article_inline_rows <> 1 OR organization_asset_rows <> 59 THEN
    RAISE EXCEPTION
      'purge_unreferenced_media_placeholders_shape_changed: expected 68/1/59 = 128, found %/%/% = %',
      site_default_rows, article_inline_rows, organization_asset_rows, pending;
  END IF;

  SELECT count(*) INTO platform_rows
    FROM public.media AS m
   WHERE m.state = 'active'
     AND m.purpose = 'organization-asset'
     AND m.organization_id = '7e27727d-b59f-4d24-998e-1bee6eeb3fa0'::uuid;

  IF platform_rows <> 1 THEN
    RAISE EXCEPTION
      'purge_unreferenced_media_placeholders_platform_asset_missing: expected the platform organization brand asset to stay active, found %', platform_rows;
  END IF;
END;
$$;
WITH archived AS (
  UPDATE public.media AS m
     SET state = 'archived',
         version = m.version + 1,
         updated_at = now()
   WHERE m.state = 'active'
     AND m.purpose IN ('site-default', 'article-inline', 'organization-asset')
     AND (m.purpose <> 'organization-asset'
          OR m.organization_id <> '7e27727d-b59f-4d24-998e-1bee6eeb3fa0'::uuid)
     AND NOT EXISTS (SELECT 1 FROM public.site_settings AS s
                      WHERE s.logo_media_id = m.id OR s.favicon_media_id = m.id OR s.default_media_id = m.id)
     AND NOT EXISTS (SELECT 1 FROM public.articles AS a WHERE a.lead_media_id = m.id)
     AND NOT EXISTS (SELECT 1 FROM public.article_sites AS x WHERE x.custom_image_media_id = m.id)
     AND NOT EXISTS (SELECT 1 FROM public.articles AS b
                      WHERE b.body_json::text ~ ('media:' || m.id::text || '(?![0-9a-f-])'))
  RETURNING m.organization_id, m.id, m.purpose, m.state, m.version, m.object_key
), scheduled AS (
  INSERT INTO public.object_cleanup_tasks (
    organization_id, id, object_key, reason, status, attempts, next_attempt_at, created_at, updated_at
  )
  SELECT organization_id, gen_random_uuid(), object_key, 'media.archived', 'pending', 0, now(), now(), now()
    FROM archived
  RETURNING organization_id
), audited AS (
  INSERT INTO public.audit_logs (
    organization_id, id, actor_type, actor_id, entry_point, action, target_type,
    target_id, outcome, changed_fields, before, request_id
  )
  SELECT organization_id,
         gen_random_uuid(),
         'system'::public.audit_actor_type,
         'migration:purge_unreferenced_media_placeholders',
         'worker'::public.audit_entry_point,
         'media.archive',
         'media',
         id::text,
         'succeeded'::public.audit_outcome,
         ARRAY['state'],
         jsonb_build_object(
           'id', id,
           'purpose', purpose,
           'state', 'active',
           'objectKey', object_key
         ),
         'migration:211'
    FROM archived
  RETURNING organization_id
)
SELECT (SELECT count(*) FROM archived) AS archived,
       (SELECT count(*) FROM scheduled) AS scheduled,
       (SELECT count(*) FROM audited) AS audited;
DO $$
DECLARE
  remaining integer;
  platform_rows integer;
  scheduled integer;
BEGIN
  SELECT count(*) INTO remaining
    FROM public.media AS m
   WHERE m.state = 'active'
     AND m.purpose IN ('site-default', 'article-inline', 'organization-asset')
     AND (m.purpose <> 'organization-asset'
          OR m.organization_id <> '7e27727d-b59f-4d24-998e-1bee6eeb3fa0'::uuid)
     AND NOT EXISTS (SELECT 1 FROM public.site_settings AS s
                      WHERE s.logo_media_id = m.id OR s.favicon_media_id = m.id OR s.default_media_id = m.id)
     AND NOT EXISTS (SELECT 1 FROM public.articles AS a WHERE a.lead_media_id = m.id)
     AND NOT EXISTS (SELECT 1 FROM public.article_sites AS x WHERE x.custom_image_media_id = m.id)
     AND NOT EXISTS (SELECT 1 FROM public.articles AS b
                      WHERE b.body_json::text ~ ('media:' || m.id::text || '(?![0-9a-f-])'));

  IF remaining <> 0 THEN
    RAISE EXCEPTION 'purge_unreferenced_media_placeholders_incomplete: % unreferenced rows remain active', remaining;
  END IF;

  SELECT count(*) INTO platform_rows
    FROM public.media AS m
   WHERE m.state = 'active'
     AND m.purpose = 'organization-asset'
     AND m.organization_id = '7e27727d-b59f-4d24-998e-1bee6eeb3fa0'::uuid;

  IF platform_rows <> 1 THEN
    RAISE EXCEPTION 'purge_unreferenced_media_placeholders_platform_asset_lost: % platform rows active', platform_rows;
  END IF;

  SELECT count(*) INTO scheduled
    FROM public.object_cleanup_tasks
   WHERE reason = 'media.archived' AND status = 'pending';

  RAISE NOTICE 'purge_unreferenced_media_placeholders_done: % cleanup tasks pending', scheduled;
END;
$$;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (211, 'purge_unreferenced_media_placeholders', 'sha256:369b1119da9cce3418f5d8f992a9c8f1f3979c88b1b0b048cbb0495fde8d6c2f');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('811e79a23a53f2d9aae2e19e827052d11cd1b966c10a4bcfc2c8fc4c8342aea7', 1790560800000);

-- ----------------------------------------------------------------------
-- 20260928030000_media_object_key_reconciliation_reader
-- ----------------------------------------------------------------------
-- Cross-tenant reader for the media-versus-R2 reconciliation, plus the two
-- indexes that keep it affordable.
--
-- The reconciliation compares what the R2 buckets actually hold against what
-- `media` claims to hold. Two drift classes showed up in the 2026-09-28 audit
-- and neither was visible before, because no query ever looked at both sides:
--
--   * a `media` row whose `object_key` was never written. Four rows from the
--     2026-09-24 organization-asset backfill point at a key that does not
--     exist, so `/api/network/media/{id}` would 404 for them. The upload used
--     an `o/{org}` prefix spliced from the neighbouring Organization id while
--     the row recorded the correct key, so the `media_owner_prefix` check
--     passed on the database side and nothing flagged the storage side.
--
--   * an R2 object no `media` row can address. The bytes from those same four
--     uploads sit under a prefix that matches no Organization, so no
--     reconciliation, invalidation, or cleanup queue could ever name them.
--
-- Reading every Organization's media rows needs a role that is not
-- tenant-scoped: the `media` row-level policies compare `organization_id`
-- against `indicate_private.current_organization_id()`, which is NULL for the
-- system reconciler, so the runtime role sees zero rows. This function is the
-- same shape as `read_runtime_config_active_domains` — `STABLE`, `SECURITY
-- DEFINER`, a pinned `search_path`, `REVOKE`d from `PUBLIC` and granted only to
-- the runtime role — and returns keys only, never object bytes, so the
-- reconciliation cannot become a read path for tenant media.
--
-- The reconciliation never deletes from this function's output. It reports
-- drift; removal still happens through `object_cleanup_tasks` and the
-- reconciler that claims them, so an operator decision and a durable queue row
-- stand between the report and an irreversible delete.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
CREATE OR REPLACE FUNCTION indicate_private.read_media_object_keys()
 RETURNS TABLE(organization_id uuid, media_id uuid, object_key text, thumb_object_key text, purpose text, state media_state)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'indicate_private'
AS $function$
  SELECT m.organization_id, m.id, m.object_key, m.thumb_object_key, m.purpose, m.state
  FROM public.media AS m
  WHERE m.object_key IS NOT NULL
  ORDER BY m.organization_id, m.id;
$function$;
REVOKE ALL ON FUNCTION indicate_private.read_media_object_keys() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION indicate_private.read_media_object_keys() TO indicate_runtime;
CREATE INDEX IF NOT EXISTS media_object_key_idx ON public.media (object_key) WHERE object_key IS NOT NULL;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (212, 'media_object_key_reconciliation_reader', 'sha256:4e866b10ad9a9cdabc60ec5ae9bae0832c8fae0367f9808cdcec997262175ef6');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('b6cb21b47d9490fb11ce811f48cdddba7e9f0fa46b2f94d5fc6beb76a08ca339', 1790564400000);

-- ----------------------------------------------------------------------
-- 20260928040000_publisher_dedupe_and_article_dates
-- ----------------------------------------------------------------------
-- Drop the orphaned publisher batch, carry its city metadata forward, and close
-- the two gaps that let the duplicate provisioning pass land unnoticed.
--
-- The 59 unit publishers were written twice. The 2026-09-08 pass wrote one
-- publisher per unit inside that unit's own tenant organization; the 2026-09-13
-- pass wrote the same 59 names again inside the platform organization and is the
-- one the 7,906 official_affiliations rows point at. The first pass therefore
-- holds the only copy of `contacts.city` and has no referrer at all: no article,
-- no affiliation, no audit row, and none of its 59 organizations owns a site.
-- The second pass lost `city` when the R2 logo backfill rewrote `contacts`, so
-- the deletion merges that single field forward rather than dropping it with the
-- row.
--
-- `logoUrl` is deliberately not merged. The first pass points at per-unit logos
-- that are all archived, while the second pass points at the active shared
-- organization asset, so copying the field would repoint 59 verified publishers
-- at media that no longer serves.
--
-- The unique constraint could not have prevented the original incident, because
-- the two passes landed in different organizations. It closes the same hole
-- within one organization, which is where a re-run of the centralized pass would
-- collide.
--
-- `articles.published_at` was left null by the import even though every article
-- has published assignments carrying the editorial date. Delivery renders the
-- assignment timestamp, so the column does not change a rendered page today, but
-- a null editorial date is not a state any sort, export, or reader of the table
-- can survive.
--
-- The guard refuses to run unless the shape is exactly the one audited: 118 unit
-- rows over 59 names, and no referrer of any kind on the older row of each name.

DO $migration$
DECLARE
  unit_rows integer;
  unit_names integer;
  orphan_referrers integer;
BEGIN
  WITH ranked AS (
    SELECT
      id,
      name,
      row_number() OVER (PARTITION BY name ORDER BY created_at, id) AS rank_in_name
    FROM public.publishers
    WHERE type = 'correctional_institution'
  )
  SELECT
    count(*),
    count(DISTINCT name),
    count(*) FILTER (
      WHERE rank_in_name = 1
        AND (
          EXISTS (SELECT 1 FROM public.articles AS article WHERE article.publisher_id = ranked.id)
          OR EXISTS (SELECT 1 FROM public.official_affiliations AS affiliation WHERE affiliation.publisher_id = ranked.id)
          OR EXISTS (
            SELECT 1
            FROM public.audit_logs AS log
            WHERE log.target_id = ranked.id::text
          )
        )
    )
  INTO unit_rows, unit_names, orphan_referrers
  FROM ranked;

  IF unit_rows <> 118 OR unit_names <> 59 OR orphan_referrers <> 0 THEN
    RAISE EXCEPTION
      'publisher_dedupe_unexpected_shape: rows=% names=% orphan_referrers=%',
      unit_rows, unit_names, orphan_referrers;
  END IF;

  WITH ranked AS (
    SELECT
      id,
      name,
      contacts,
      row_number() OVER (PARTITION BY name ORDER BY created_at, id) AS rank_in_name
    FROM public.publishers
    WHERE type = 'correctional_institution'
  )
  UPDATE public.publishers AS live
  SET contacts = live.contacts || jsonb_build_object('city', orphan.contacts ->> 'city'),
      updated_at = now()
  FROM ranked AS orphan
  WHERE orphan.rank_in_name = 1
    AND orphan.contacts ->> 'city' IS NOT NULL
    AND live.type = 'correctional_institution'
    AND live.name = orphan.name
    AND NOT (live.contacts ? 'city');

  WITH ranked AS (
    SELECT
      id,
      row_number() OVER (PARTITION BY name ORDER BY created_at, id) AS rank_in_name
    FROM public.publishers
    WHERE type = 'correctional_institution'
  )
  DELETE FROM public.publishers AS publisher
  USING ranked
  WHERE ranked.id = publisher.id
    AND ranked.rank_in_name = 1;
END
$migration$;

ALTER TABLE public.publishers
  ADD CONSTRAINT publishers_org_name_unique UNIQUE (organization_id, name);

UPDATE public.articles AS article
SET published_at = assignment.published_at
FROM (
  SELECT article_id, min(published_at) AS published_at
  FROM public.article_sites
  WHERE state = 'published'
    AND published_at IS NOT NULL
  GROUP BY article_id
) AS assignment
WHERE assignment.article_id = article.id
  AND article.published_at IS NULL;

INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (213, 'publisher_dedupe_and_article_dates', 'sha256:3bb7328c1f3bb1c167b9335f37869f8de735cd997aa673060429610a97dc5332');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('003ab0533d4f999eb718c1a1da1573c04d4624bb1becea3aec837ec433e0a314', 1790593200000);

-- ----------------------------------------------------------------------
-- 20260928050000_publisher_provenance_audit
-- ----------------------------------------------------------------------
-- Record the provenance of the 60 publishers that were provisioned outside the
-- application layer, so the audit trail stops contradicting the data.
--
-- `hygiene:publishers` flags a verified, active publisher with no audit row as
-- something the application layer would never produce, and it was right: the 59
-- unit publishers and the platform publisher were written by a bulk load, not by
-- the dashboard. The rows claim `verification_status = 'verified'`, which the
-- application only ever sets after a membership-backed verification, so the
-- verified state currently has no evidence behind it.
--
-- This records what actually happened rather than inventing an approval. The
-- actor is `system`, the entry point is `worker`, and the action names the real
-- mechanism, so the row documents an out-of-band load instead of fabricating a
-- human decision that never occurred. `after` carries the batch the row came
-- from so the original timestamp survives in the record even though the chain
-- trigger overwrites `occurred_at` with the moment of writing.
--
-- The insert is additive and idempotent: a publisher that already has a trail is
-- skipped, so re-running the migration cannot duplicate history. The table is
-- append-only, and the chain trigger signs each row as it lands.
--
-- This does not make the load legitimate. It makes the gap visible and dated,
-- which is the part a reader of the audit log can act on.

DO $migration$
DECLARE
  untrailed integer;
  to_record integer;
BEGIN
  SELECT count(*) INTO untrailed
  FROM public.publishers AS publisher
  WHERE publisher.status = 'active'
    AND NOT EXISTS (
      SELECT 1
      FROM public.audit_logs AS log
      WHERE log.target_type = 'publisher'
        AND log.target_id = publisher.id::text
    );

  SELECT count(*) INTO to_record
  FROM public.publishers;

  IF untrailed <> to_record THEN
    RAISE EXCEPTION
      'publisher_provenance_partial: % of % active publishers still lack a trail',
      untrailed, to_record;
  END IF;

  INSERT INTO public.audit_logs (
    organization_id,
    id,
    actor_type,
    actor_id,
    entry_point,
    action,
    target_type,
    target_id,
    outcome,
    changed_fields,
    before,
    after,
    request_id
  )
  SELECT
    publisher.organization_id,
    gen_random_uuid(),
    'system',
    'db:publisher-provenance',
    'worker',
    'publisher.provisioned_out_of_band',
    'publisher',
    publisher.id::text,
    'succeeded',
    ARRAY['status', 'verification_status'],
    NULL,
    jsonb_build_object(
      'name', publisher.name,
      'type', publisher.type,
      'verification_status', publisher.verification_status,
      'provenance', 'bulk-load-outside-application',
      'evidence_reference', publisher.evidence_reference,
      'provisioned_at', publisher.created_at
    ),
    'db:publisher-provenance'
  FROM public.publishers AS publisher
  WHERE publisher.status = 'active'
    AND NOT EXISTS (
      SELECT 1
      FROM public.audit_logs AS log
      WHERE log.target_type = 'publisher'
        AND log.target_id = publisher.id::text
    );
END
$migration$;

INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (214, 'publisher_provenance_audit', 'sha256:d77e774f15e1aa349f9c82be2e0c9fffbe62039d243b51bebb3a083c1b9aeff3');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('c89571253d69d135e056fb4e0e2ac682372015ebea421d5b682e9edf60e3ed9b', 1790596800000);

-- ----------------------------------------------------------------------
-- 20260928060000_article_updated_at_restore
-- ----------------------------------------------------------------------
-- Undo the editorial timestamp that the publisher-dedupe migration stamped onto
-- all 30 articles.
--
-- That migration backfilled `articles.published_at` from the published
-- assignments. The correction was right, but `articles_touch_updated_at` fires on
-- any row change, so the backfill also rewrote `articles.updated_at` to the moment
-- it ran. Delivery renders `updatedAt` as the "Diperbarui" line, so every article
-- page started claiming it had been revised today even though nothing had been
-- edited. The stored value before the backfill was a single bulk timestamp from
-- the 2026-09-27 import, so the per-row `created_at` is the closest truthful
-- record of when each article was last touched.
--
-- The trigger has to stand down for the write, because it would otherwise stamp
-- the row again. It is disabled and re-enabled inside the same transaction, so a
-- failure anywhere rolls the whole migration back with the trigger still armed.
--
-- The guard matches the exact timestamp the backfill produced. A row edited since
-- then carries a different value and is left alone, so this can never overwrite a
-- real editorial change that happened after the backfill.

DO $migration$
DECLARE
  stamped integer;
  total integer;
BEGIN
  SELECT count(*) INTO stamped
  FROM public.articles
  WHERE updated_at = '2026-09-28 11:21:12.472508+00'::timestamptz;

  SELECT count(*) INTO total FROM public.articles;

  IF stamped <> total THEN
    RAISE EXCEPTION
      'article_updated_at_restore_unexpected_shape: stamped=% total=%',
      stamped, total;
  END IF;

  ALTER TABLE public.articles DISABLE TRIGGER articles_touch_updated_at;

  UPDATE public.articles
  SET updated_at = created_at
  WHERE updated_at = '2026-09-28 11:21:12.472508+00'::timestamptz;

  ALTER TABLE public.articles ENABLE TRIGGER articles_touch_updated_at;
END
$migration$;

INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (215, 'article_updated_at_restore', 'sha256:3667c5652edeadffc32296b693a5a0d28eeb87a0ab346a97c7fb94e2cca01fef');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('d644af1766e59173b94d44c315767d135f6e21ad339f3ff96b86c9093df9ccbe', 1790597000000);

-- ----------------------------------------------------------------------
-- 20260928070000_default_article_category_berita
-- ----------------------------------------------------------------------
-- Relabel the default article category from `Umum` (slug `umum`) to `Berita`
-- (slug `berita`).
--
-- Ledger 206 seeded `Umum` into every organization that owns a publisher so an
-- article could never be filed under no category. The label was the wrong call
-- for an Indonesian newsroom: `Umum` reads as "general" and "miscellaneous" in
-- one word, so an editor skims past it, and the composer pre-selects it, which
-- means every story nobody deliberately filed landed in a bucket nobody
-- browses. `Berita` is the desk an editor expects an unfiled story to sit in.
--
-- The row is renamed in place instead of being deleted and re-seeded so the
-- category id never moves; that leaves every `articles.category_id` and
-- `article_categories` row untouched. All sixty seeded rows were still
-- unreferenced when this was written, but renaming in place makes that not
-- matter.
--
-- One organization (`Pengelola Platform`) already owned an active `Berita`
-- category carrying 30 articles of its own. `categories_organization_slug_unique`
-- makes a blind rename collide there, so that organization's seeded row is
-- archived instead: its existing `Berita` already is the label the default
-- wants, and the duplicate is retired rather than renamed onto the same slug.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
DO $$
DECLARE
  referenced integer;
BEGIN
  SELECT count(*) INTO referenced
    FROM public.categories AS seeded
   WHERE seeded.slug = 'umum'
     AND (EXISTS (SELECT 1 FROM public.articles WHERE articles.category_id = seeded.id)
       OR EXISTS (SELECT 1 FROM public.article_categories WHERE article_categories.category_id = seeded.id));

  IF referenced <> 0 THEN
    RAISE EXCEPTION 'default_category_berita_blocked: % umum categories are still referenced by articles', referenced;
  END IF;
END;
$$;
UPDATE public.categories AS seeded
   SET status = 'archived'::public.record_status,
       version = seeded.version + 1,
       updated_at = now()
  FROM public.categories AS keeper
 WHERE keeper.organization_id = seeded.organization_id
   AND keeper.slug = 'berita'
   AND keeper.status = 'active'::public.record_status
   AND seeded.slug = 'umum'
   AND seeded.status = 'active'::public.record_status
   AND seeded.id <> keeper.id;
UPDATE public.categories
   SET name = 'Berita',
       slug = 'berita',
       version = version + 1,
       updated_at = now()
 WHERE slug = 'umum'
   AND status = 'active'::public.record_status
   AND NOT EXISTS (
     SELECT 1 FROM public.categories AS keeper
      WHERE keeper.organization_id = public.categories.organization_id
        AND keeper.slug = 'berita'
   );
DO $$
DECLARE
  expected integer;
  resolved integer;
  missing integer;
  leftover integer;
BEGIN
  SELECT count(*) INTO expected
    FROM (SELECT DISTINCT organization_id FROM public.publishers) AS publisher_org;

  SELECT count(*) INTO resolved
    FROM public.categories
   WHERE slug = 'berita'
     AND status = 'active'
     AND EXISTS (SELECT 1 FROM public.publishers AS p WHERE p.organization_id = categories.organization_id);

  SELECT count(*) INTO missing
    FROM (SELECT DISTINCT organization_id FROM public.publishers) AS publisher_org
   WHERE NOT EXISTS (
     SELECT 1 FROM public.categories AS c
      WHERE c.organization_id = publisher_org.organization_id
        AND c.slug = 'berita'
        AND c.status = 'active'
   );

  SELECT count(*) INTO leftover
    FROM public.categories
   WHERE slug = 'umum'
     AND status = 'active';

  IF missing <> 0 OR leftover <> 0 THEN
    RAISE EXCEPTION 'default_category_berita_incomplete: % publishing organizations without an active berita category, % active umum rows left', missing, leftover;
  END IF;

  RAISE NOTICE 'default_category_berita_done: % publishing organizations, % berita categories', expected, resolved;
END;
$$;
