INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('b41fe6f64d31744110e6e6249189f2d7a4f39bc6c7fc99b048a11bcfe5887b28', 1790899200000);

-- ----------------------------------------------------------------------
-- 20261003040000_backfill_article_author
-- ----------------------------------------------------------------------
-- Give the unnamed articles a byline so `NewsArticle.author` is emitted.
--
-- `seo.ts` only emits `author` when an article resolves a display name, and
-- Google lists `author` among the recommended `Article` properties: it drives
-- the byline shown in search results. Fourteen active articles had
-- `author_id IS NULL`, so their structured data silently omitted the field
-- while the thirty that name "Indicate" carried it. The corpus had two
-- bylines only because those fourteen were left unset, not because they
-- belong to a different desk.
--
-- Scoped to the operator organization so a tenant's own articles are never
-- reassigned, and to `status = 'active'` so drafts stay editable. The guard is
-- `author_id IS NULL`, so re-running matches nothing and a row an editor has
-- since attributed is left alone. Version churn is intentional: `author_id` is
-- a real editorial change, and the optimistic-concurrency token must move with
-- it.
UPDATE public.articles AS article
   SET author_id = (
         SELECT author.id
           FROM public.authors AS author
          WHERE author.display_name = 'Indicate'
            AND author.organization_id = article.organization_id
       ),
       version = article.version + 1,
       updated_at = now()
  FROM public.organizations AS organization
 WHERE article.organization_id = organization.id
   AND organization.kind = 'operator'
   AND article.status = 'active'
   AND article.author_id IS NULL
   AND EXISTS (
         SELECT 1
           FROM public.authors AS candidate
          WHERE candidate.display_name = 'Indicate'
            AND candidate.organization_id = article.organization_id
       );

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('ee62a52cdd0399874d6cdaa3a5ec537a297b90c0e5b98a7f0669d32f321e8b8b', 1790985600000);

-- ----------------------------------------------------------------------
-- 20261003120000_site_comments_enabled
-- ----------------------------------------------------------------------
-- Give each site an explicit reader-comment switch, defaulting to off.
--
-- The platform ships one Disqus forum for the whole network, so the switch is
-- per site rather than per tenant account: an apex site and its regional
-- children decide independently whether their own article pages carry a
-- comment thread. Left at the database default, every existing and future site
-- inherits `false`, which is the only safe starting point -- the embed is a
-- third-party processor that profiles readers, and the public privacy copy
-- promises that reader pages install no third-party trackers.
--
-- A constant `NOT NULL DEFAULT false` needs no backfill statement and no table
-- rewrite on PostgreSQL 11 or newer: the default is materialized on read, so
-- the 4,422 existing rows are untouched and the ACCESS EXCLUSIVE lock is held
-- only for the catalog change. `IF NOT EXISTS` is there because this migration
-- is applied by hand, and a retry after a partial apply must not fail on a
-- column that is already there.
--
-- Ledger version 244 follows the live `max(version)`, which is 243. Journal idx
-- 243 (`backfill_article_author`) carries no self-registration row and was
-- never applied here, so the numbering offset that the missing migration 187
-- introduced closes at this row rather than skipping a version.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
ALTER TABLE public.site_settings
  ADD COLUMN IF NOT EXISTS comments_enabled boolean NOT NULL DEFAULT false;
INSERT INTO public.indicate_schema_migrations(version, name, checksum)
VALUES (244, 'site_comments_enabled', 'sha256:8c542bde2f5c4772b183b9a3533fe3cf980a3546cbd3a3c0a81ab605d325fba2');

INSERT INTO drizzle."__drizzle_migrations" ("hash", "created_at") VALUES ('ad4a2bb5a6249c879b441e8d8a51ed827613628a49a617a02032eef7f0b4d093', 1791028800000);

-- ----------------------------------------------------------------------
-- 20261004000000_ads_full_schema
-- ----------------------------------------------------------------------
-- Full advertising schema: catalog, ownership, scheduling, tenant switches, events.
--
-- advertisers own campaigns; campaigns group creatives; ad_placements bind one
-- creative to one semantic slot with an optional site/template/device scope and
-- a validity window. tenant_ad_settings carries the per-site slot switch and an
-- optional custom creative, outranking the transitional `site_settings.seo.ads`
-- carrier per slot. ad_impressions and ad_clicks are append-only event rows
-- keyed by day so a future rollup can aggregate without scanning `created_at`.
--
-- ad_slots is a global catalog like `template_presets`: slot meaning is
-- network-wide, so it carries no organization column and its RLS policy is a
-- plain runtime accessor. Every other table is tenant-scoped with the standard
-- organization guard forced on the runtime role. Event rows point at placements
-- and creatives with SET NULL so deleting a campaign never orphans analytics.
--
-- The seed mirrors `src/modules/ads/slots.ts`; ON CONFLICT keeps a retried
-- apply idempotent without touching edited rows.
--
-- Ledger version 245 follows the live `max(version)`, which is 244.
--
-- Body digest (reproducible): LF-normalize this file, substitute the 64-hex
-- checksum literal below with 64 zeros, SHA-256 the complete UTF-8 bytes.
CREATE TYPE "public"."ad_creative_kind" AS ENUM('image', 'html', 'provider');
CREATE TYPE "public"."ad_campaign_status" AS ENUM('draft', 'scheduled', 'active', 'paused', 'ended');
CREATE TABLE "public"."advertisers" (
  "organization_id" uuid NOT NULL,
  "id" uuid NOT NULL,
  "name" text NOT NULL,
  "contact_email" text,
  "status" "public"."record_status" DEFAULT 'active' NOT NULL,
  "version" integer DEFAULT 1 NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "advertisers_pk" PRIMARY KEY("organization_id","id")
);
CREATE UNIQUE INDEX "advertisers_id_unique" ON "public"."advertisers" USING btree ("id");
CREATE UNIQUE INDEX "advertisers_organization_name_unique" ON "public"."advertisers" USING btree ("organization_id","name");
CREATE INDEX "advertisers_organization_status_idx" ON "public"."advertisers" USING btree ("organization_id","status");
ALTER TABLE "public"."advertisers" ADD CONSTRAINT "advertisers_organization_id_organizations_id_fk" FOREIGN KEY ("organization_id") REFERENCES "public"."organizations"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "public"."advertisers" ADD CONSTRAINT "advertisers_version_positive" CHECK ("advertisers"."version" > 0);
CREATE TABLE "public"."campaigns" (
  "organization_id" uuid NOT NULL,
  "id" uuid NOT NULL,
  "advertiser_id" uuid NOT NULL,
  "name" text NOT NULL,
  "status" "public"."ad_campaign_status" DEFAULT 'draft' NOT NULL,
  "priority" integer DEFAULT 0 NOT NULL,
  "starts_at" timestamp with time zone,
  "ends_at" timestamp with time zone,
  "version" integer DEFAULT 1 NOT NULL,
